quests[27472] = { id = 27472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Godfrey", description = "You are unwavering in your loyalty to the Forsaken, {name}. Know that what you have done for us - for the Horde - will not go unnoticed. With Lord Godfrey and his men recovered, we will have a great advantage over the Gilneas Liberation Front and the rest of the Alliance dogs.\n\nNow stand by my side as Lord Godfrey is reborn as one of us. Together we will bring him and his men into the fold.", completion = "Today marks a new beginning for the Forsaken and the end of the Alliance in Lordaeron!", objectives = "Stand by Lady Sylvanas Windrunner as she initiates Lord Godfrey and his men.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27473] = { id = 27473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Shaking in Ironforge", description = "Things have grown worse in Ironforge, {name}.  Please, speak with Stormcaller Mylra in Ironforge and see if you can lend a hand in some way.", completion = "It is good that you've come, {name}.  We need all the help we can get with the situation here.", objectives = "Speak with Stormcaller Mylra in Ironforge.Things have grown worse in Ironforge, {name}. Please, speak with Stormcaller Mylra in Ironforge and see if you can lend a hand in some way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27474] = { id = 27474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Barrier", description = "While Godfrey and I make preparations for our assault upon Gilneas, I want you to lead our attack upon Ambermill, directly east of here.\n\nThe former Dalaran magi of Ambermill have erected a magical barrier that somehow cloaks them from vision. They currently reside within some type of pocket dimension, awaiting orders from the Alliance to begin their attack. We must prevent their assault by making a pre-emptive strike. Venture to Ambermill and find information that would grant us access to the mages.", progress = "Have you found anything yet?", completion = "Clever mages. The codex is sealed by a magical ward.\n\nPity that they weren't clever enough to realize that former archmages of Dalaran are now Forsaken.", objectives = "Find the Ambermill Codex.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27475] = { id = 27475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Servitors", description = "The magi of Ambermill have employed foul magic to keep us away. Elemental servitors, created with immunities that we cannot breach, protect their territory.\n\nVenture east to Ambermill and slay the unyielding elemental servitors that guard the town and recover their cores. Bring their cores back to me so that I may devise a method by which we are able to destroy them all!", progress = "Have you recovered the servitor cores?", completion = "Well done, {name}. The praise the Banshee Queen lavishes upon you is apparently not unfounded.", objectives = "Retrieve 6 Servitor Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27476] = { id = 27476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalar Dawnweaver", description = "Take the codex and travel north to the Sepulcher. Once there, find Dalar Dawnweaver. Dalar is a former archmage of the Kirin Tor. Surely he will be able to bring down the protective wards surrounding this codex and pry its secrets loose.\n\nHurry, {name}.", progress = "Yes? What is it?", completion = "The Dark Lady requires my expertise? Well of course! Give it here, boy.", objectives = "Deliver the Ambermill Codex to Dalar Dawnweaver at the Sepulcher in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27477] = { id = 27477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpulent One", description = "North of here and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor.  Borelgore has been known to devour others who tried to hunt him.", completion = "Keep this up and I may have to keep you here at Eastwall, {race}.", objectives = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27478] = { id = 27478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relios the Relic Keeper", description = "The Dark Lady is correct in her assertion that I am able to unlock the codex. Unfortunately, I need a signet ring from a Dalaran archmage to do it. My own ring was taken when I died many years ago, but there still might be a way.\n\nWhile Dalaran has floated away, the outskirts of the city remain. Far to the east lie the ruins of Dalaran. It is there that you will find an archmage known as Relios. \"Take\" his signet ring and bring it back to me.\n\nYou may use the portal behind me to get to the crater.", progress = "Did you recover a Dalaran Archmage's Signet Ring?", completion = "Perfect. I hope this wasn't too much trouble to come by, {name}. Relios was a pupil of mine back when I was a mortal man thereby making him a competent and formidable adversary. I suppose I could have warned you ahead of time.\n\nNow, let us see the ring.\n\n\n\nThere we are...", objectives = "Find a Dalaran Archmage's Signet Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27479] = { id = 27479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Righteous Indignation", description = "The Mossflayers of Zul'Mashar spit in the face of the Light!  They cannibalize, they criminalize, they prioritize the forces of evil over good!  I advise that you remove their eyes, and give rise to the demise and the goodbyes of the unwise!\n\nYou will travel north, and you will rain down on them with righteous justice and indignation, {name}.  The fury that they have wrought in the eyes of the Light shall be channeled through you.", progress = "<Deacon Andaal is deep in prayer.>", completion = "Oh, hallelujah, and praise, praise be to the Light, my brother!", objectives = "Obtain 30 Mossflayer Eyes from Mossflayer trolls in Zul'Mashar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27480] = { id = 27480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ley Energies", description = "The arcane remnant pulses with strange energy. Perhaps you should search for more remnants. Surely Dalar would be interested in such a find.", progress = "What's that you've got there, {name}?", completion = "Smart boy! I can most definitely use these arcane remnants in my studies. Indeed, Dalaran was built upon a massive ley line. It's no wonder, then, that such things exist at the crater.", objectives = "Recover 8 Arcane Remnants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27481] = { id = 27481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Ziggurat", description = "It is time that I asked a favor of you, {name}.\n\nFar to the north of Eastwall Tower, hidden among the hills, is the Mossflayer capital city of Zul'Mashar.  It was here that I was born, and here that I died.\n\nThe traitor, Thresh'jin, sits atop Zul'Mashar's ziggurat.  It was my every right to be there, but he took the seat from me with treachery and deceit.  He is not strong.  He is weak.\n\nI will meet you in Zul'Mashar, and we will kill him.  Your strength and mine.  Together.", progress = "I have waited long for this day.", completion = "My duty is not over yet.  In many ways, this was the easy step.", objectives = "Obtain the Body of Warlord Thresh'jin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27482] = { id = 27482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Flames", description = "This is the last time you will see me, {name}.  I am leaving the caravan.\n\nIf you want to continue fighting by my side, hang on to Thresh'jin's body.  I can wait for a while longer.  When you are ready to say goodbye, throw the body into the bonfire atop Zul'Mashar's ziggurat.\n\nThank you for your companionship, {name}.  You were strong.", objectives = "When you are ready to part with Vex'tul, throw Warlord Thresh'jin's body into the bonfire atop Zul'Mashar's ziggurat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27483] = { id = 27483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practical Vengeance", description = "Under ordinary circumstances I am not a vengeful man. In fact, I am somewhat of a pragmatist. You see, practicality is a paradoxical notion to vengeance. Most revenge ploys are highly impractical.\n\nBUT... in this case - since you're already going to the ruins of Dalaran - you might as well kill every Dalaran affiliated human that you see. The reasons that I want them dead range from hatred to anger to betrayal, but I assure you they are all legitimate gripes. Do this for me and I will pay you handsomely.", completion = "I thought for sure that with the death of a dozen of my most hated enemies I would feel a great burden lifted from my shoulders. Sadly, I do not feel a thing. Perhaps I am a psychopath.", objectives = "Kill any 12 Dalaran humans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27484] = { id = 27484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only One May Enter", description = "<Dalar flips through the codex.>\n\nHAHAH!\n\nOh... That's bad.\n\n<Dalar closes the codex and looks up at you.>\n\nWith this ring only ONE may enter the pocket dimension at Amber Mill. That person will then need to fight through an army of magi and kill the archmage that is generating the phase from the inside. Only then will the dimension fold, ejecting all of the magi.\n\nThe portal to entry is hidden at the back of a cave in Beren's Peril.\n\nThat's all I know. Take the ring back to Sylvanas.", progress = "What have you learned?", completion = "Only one may enter? I know just the person for this mission.\n\n<Sylvanas nods at you.>\n\nI will prepare our forces and have them at the ready.", objectives = "Take the Dalaran Archmage's Signet Ring to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27485] = { id = 27485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Welcome", description = "I'm glad you're back! Saving the world or something, I'm sure.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nCare to take a crack at earning a bit of trust with Lirastrasza at Vermillion Redoubt to the southwest? Anything that might soften her up a bit for me would be lovely.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous.", objectives = "Meet with Lirastrasza at Vermillion Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27486] = { id = 27486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Welcome", description = "Good. You're back. Saving the world again I assume.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nI need you to gain the trust of Lirastrasza at Vermillion Redoubt to the southwest. Our association with the Dragonmaw has complicated things, but I'm hoping you can ease relations.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous.", objectives = "Meet with Lirastrasza at Vermillion Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27487] = { id = 27487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ix'lar the Underlord", description = "I know we're supposed to head to Northdale, but that can wait, right?  Besides, this lovely little goblin was just telling me about some Scourge that are even closer by.\n\nSo apparently there's this nerubian underlord named Ix'lar that has been trying to make a name for himself ever since the Lich King was slain.  He's set up a camp of undead to our north.\n\nSure, Tyrosus wants us to kill banshees in Northdale.  We'll get to that.  But let's kill this nerubian first, while we're close!", completion = "I couldn't stop him.  While you and Tarenar were out, Giddy ran north all alone!\n\nTarenar, you should have known better!  Gidwin gets so impatient sometimes, and you only egg him on.  If Giddy gets into any trouble, I'm blaming you for this.", objectives = "Kill Ix'lar the Underlord and 10 of his minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27488] = { id = 27488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impatience", description = "Damn that dwarf.  He's always getting me in trouble with Fiona.  Look at her!  She won't even TALK to me!\n\nI'm going to stay here and try to mend my friendship with our worgen friend.  Would you mind going out and making sure Gidwin is alright?  I'm sure he's fine; he knows how to take care of himself.  He headed north, and he can't have gone far.", progress = "Northdale is home to a few ghosts and banshees.  Nothing ol' Giddy can't handle.", completion = "You didn't see him?  Where could he have gone then?\n\nHis... his prayer book?  Why would he leave that behind?\n\nOh...\n\nBy the Light, what have I done?", objectives = "Search for Gidwin Goldbraids in Northdale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27489] = { id = 27489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobody to Blame but Myself", description = "This is my fault.  I... I ignored his warnings, his complaints, everything.  I couldn't help myself - I saw those Scourge just beyond the tower, and I... I HAD to go kill them.\n\nArgus says that Gidwin was taken northwest, and that's our only lead, so that's where we'll head.\n\nNorthdale and the Argent Crusade be damned!  We're getting Gidwin back from those Scourge trash.", progress = "We have no time, {name}!  We must press on!", completion = "Time is wasting, {name}.  Every minute we waste gives the Scourge another chance to kill Gidwin.  If he isn't dead already.\n\nNot that I think he is.  Giddy may be a stick-in-the-mud, but when it comes down to it, he can swing the Light like a champion.", objectives = "Hop in Fiona's Caravan and ride to Northpass Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27490] = { id = 27490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SI:7 Drop", description = "Mathias Shaw and the SI:7 are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nThe Wildhammer are being kind enough to give us a lift in. The agents have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with Angus Stillmountain and get yourself a squad to drop off. You'll fly them in. A big blue X marks the spot.", progress = "I need you to escort those SI:7 agents safely to their destination, {name}.", completion = "That must have been deadly.\n\nWhile I don't approve of their methods, no one can question the effectiveness of Master Mathias Shaw and his SI:7. Not to mention that you're here. Our victory is all but assured.", objectives = "Get a Wildhammer Hellions squad from Angus Stillmountain and then escort them to the drop off point in the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27491] = { id = 27491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kor'kron Drop", description = "Garona and a detachment of the Kor'kron are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nI've called upon a local tribe of trolls to give us a lift in with their wind riders. The assassins have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with the troll chief, Jon-Jon Jellyneck and get yourself a detachment of Kor'kron to drop off. You'll fly them in. A big red X marks the spot.", progress = "I need you to get those Kor'kon assassins safely to their destination, {name}.", completion = "That must have been exciting.\n\nDespite any losses that the Kor'kron may have incurred along the way, no one will be able to doubt their effectiveness, nor that of Garona. And with you in the mix, it's only a matter of time before victory is ours.", objectives = "Get a Crushblow Wind Rider squad from Jon-Jon Jellyneck and then escort them to the drop off point in the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27492] = { id = 27492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres & Ettins", description = "As with any offensive, you first need to soften them up. We've been having a heck of a time getting in there. But someone like you... well, let's just say I have no doubt in my mind that you can get into the Twilight Gate to the southwest and teach the Bloodeye Clan ogres and ettins a thing or two!", progress = "What's the matter? You Alliance boys don't have the stomach to get the job done?\n\n<Kurdran gives you a wink.>\n\nNeed me to fly over there and kill them for you?", completion = "That's the spirit, lad! Today's already shaping up to be a good one.", objectives = "Slay 10 ogres or ettins at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27493] = { id = 27493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres & Ettins", description = "I want you to get in there past those boulders to the northwest at the Twilight Gate. Kill every Bloodeye Clan ogre and ettin in sight. Think you can handle that for me, {name}?", progress = "There are more to be killed, tauren. You do have the stomach for that, yes?", completion = "And here I thought that today couldn't get any better.\n\nI enjoy being wrong, occasionally.", objectives = "Slay 10 Bloodeye Clan ogres or ettins at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27494] = { id = 27494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Move the Mountain", description = "If the Twilight Gate is to fall, we need to get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your SI:7 agents took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", objectives = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27495] = { id = 27495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Move the Mountain", description = "If the Twilight Gate is to fall, we must get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your Kor'kron assassins took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", objectives = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27496] = { id = 27496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call in the Artillery", description = "I prefer a stand up honorable fight. These monsters deserve nothing better than to be destroyed by the weapons in our hands. However, this particular situation calls for the use of more powerful measures.\n\nTake this flare and mark each of the four buildings within the Twilight Gate to the southwest. Our cannons will handle the rest.", completion = "Thanks to you, our cannoneers hit their marks. Tell me about the situation within the Twilight Gate.", objectives = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27497] = { id = 27497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call in the Artillery", description = "A pity that we're no longer allowed to drop the Plague on our enemies. It would prove quite effective in this situation. Oh well, at least we have war machines to destroy their precious gates.\n\nI want you to take this flare. Use it to mark each of the four buildings within the Twilight Gate to the northwest. The war machines will handle the rest.", completion = "I must say that I rather enjoyed the sight of their buildings being hit.", objectives = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27498] = { id = 27498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Victor's Point to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27499] = { id = 27499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Crushblow to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27500] = { id = 27500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Cassius and Kurdran will want proof of their deaths.", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27501] = { id = 27501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Lady Cozwyn and Zaela will want proof of their deaths.", progress = "Is that blood dripping from your pack? I hope that it's not yours.", completion = "<The noble lady grins wickedly.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27502] = { id = 27502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the SI:7 forces to Master Mathias Shaw.\n\nHe's hiding somewhere up top. The SI:7 squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", objectives = "Speak with the SI:7 Squad Commander and then escort the SI:7 squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27503] = { id = 27503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the Kor'kron forces up to Garona.\n\nShe's hiding somewhere up top. The Kor'kron squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", objectives = "Speak with the Kor'kron Squad Commander and then escort the Kor'kron squad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27504] = { id = 27504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Dragons Bleed", description = "I won't be so impolite as to refuse your aid if you're offering it.\n\nWe're locked in constant battle with the twilight drakes and dragons to the south. Our strikes have not been entirely without success, but the dragons coming out of Grim Batol have been breathing some kind of corruption upon us that takes time to cleanse.\n\nVelastrasza and Baleflame are attending to our injured brothers. Go and see if you can be of help to them.", completion = "Calen has become very trusting. It is not often that strangers are permitted within the redoubt.", objectives = "Speak to Velastrasza within the Vermillion Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27505] = { id = 27505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Mending", description = "Our dragons are returning from battle covered in Twilight corrupted flame and pursued by Twilight drakes.\n\nMy menders can tend to our dragons' wounds, but they must be defended. Keep the drakes off of my menders. Lend your healing to our dragons as well if you are able.\n\nThank you for your help with this. Our battles for Grim Batol are never-ending. We need to get our strongest dragons back into the battle as soon as possible.", progress = "Keep the menders safe as they heal our wounded dragons!", completion = "We will take Grim Batol back from the Twilight's Hammer and thier allies. It may take time, but this is one charge that we cannot forsake.", objectives = "Safeguard 5 Vermillion Menders as they heal wounded dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27506] = { id = 27506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life from Death", description = "{race}, I have a task for you.\n\nTake these ruby seeds and plant them at the corpses of any dragonkin that you come across. Twilight or Vermillion, whelping or dragon, it matters not. We need to see that their bodies are returned to the earth so that life can continue to flourish.\n\nIn death, there should always be new life. This may be our one consolation during times of war and great tragedy.", progress = "Have you done as I asked?", completion = "In this, we deny Deathwing the destruction that he so passionately seeks. In this, life continues.", objectives = "Plant Ruby Seeds at the corpses of 6 dragonkin within the Vermillion Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27507] = { id = 27507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroaching Twilight", description = "Fragile Twilight invaders litter the redoubt. They're pouring in from somewhere to the west.\n\nThere can be no mercy offered to them within this hallowed place. Whatever violence grips your moral heart, release it upon them.", completion = "You have a talent for killing I see. In times like these, that has its place.", objectives = "Kill 12 Twilight invaders within the Vermillion Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27508] = { id = 27508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Far from the Nest", description = "Look... I know you have no reason to be fond of me, just as I'm not terribly fond of you, but I need any help I can get.\n\nOur eggs are being stolen by these Twilight invaders. I have no doubt that they want to take them back to Grim Batol to experiment on and pervert. I will NOT let that happen.\n\nIf you truly do want to help us, stop them! Recover the eggs. Bring them back to me.", progress = "Twilight dragons were born of these disgusting experiments of theirs. The Twilight's Hammer have gone too far. Deathwing has gone too far.", completion = "I don't know if you did this for me or the young inside these eggs, but it doesn't really matter, either way it's clear that you want to be an ally of our flight. I appreciate that.\n\nI cannot forgive the attacks by your allies against my brood, but for now, it seems you have chosen the right side.", objectives = "Recover 6 Vermillion Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27509] = { id = 27509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach in the Defenses", description = "Every inch of air and every hill surrounding the redoubt is constantly under the watchful eye of Lira's drakes. They must have found a way into the shrine from beneath.\n\nTake this Flashgrowth mote. It should prove more than sufficient to close any hole, tunnel, or portal they might have used to get inside our defenses.\n\nFind the breach in our defenses. Close it.", completion = "Well done. Thank you, {race}.\n\nI will not be so foolish as to let such an oversight happen again.", objectives = "Find the source of the Twilight's Hammer in the Vermillion Redoubt and destroy it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27510] = { id = 27510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wolf in Bear's Clothing", description = "These worgen take us for fools! One would think that only an idiot would mistake one of their druids in bear form as a real bear. Unfortunately, there are many idiots here at the Forsaken Front. We've already lost a few battalions to organized worgen bear attacks. Yes, it's even more idiotic than it sounds.\n\nDirectly east of here, heading towards Hillsbrad, you will find worgen druids roaming the woods, masquerading as bears. Kill them and make our southern supply line safe again.", completion = "I only hope that we don't end up getting beat down by inconspicuous birds, cats and trees next... or seals. Could you imagine it?", objectives = "Kill 10 Inconspicuous Bears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27511] = { id = 27511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thrill of Discovery", description = "What a find! And somehow it's all remained untouched by plunderers...\n\nListen, {name}. I need to document this site before we disturb anything. While I do, why don't you have a look around - you know, explore a bit. You've earned it.\n\nKeep your eyes open for anything unusual.\n\nOh! And please... don't break anything, ok?", completion = "Your exploration of the Chamber of the Stars has yielded more questions than answers...", objectives = "Explore the Chamber of the Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27512] = { id = 27512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter I", description = "<Sylvanas hands you the signet ring.>\n\nTake the ring and make your way to Beren's Peril, southeast of here, located in a cave in the hills. Once there, search the cave for the portal to the pocket dimension that conceals the Ambermill magi.\n\nI will communicate with you through your thoughts, {name}. Once you have reached the portal I will give you your marching orders.", progress = "<The portal hums.>", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYes, this is it. Now run the ring along the runes of the portal and you should become attuned for transdimensional travel.", objectives = "Find the Ambermill Dimensional Portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27513] = { id = 27513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter II", description = "<The Banshee Queen's words float in your head.>\n\nYou are now ready to use the portal. Be warned, {name}, once you step through you will appear in another dimension at Ambermill. There will be a hundred, perhaps a thousand, magi waiting to kill you.\n\nYou must persevere and kill all in your path.", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nExcellent work, {name}. Now to eject them into our waiting hands!", objectives = "Kill 20 Ambermill mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27514] = { id = 27514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird Down! Bird Down!", description = "While you were fighting along the coast, I spotted a gryphon tumble out of the clouds almost due west of here.\n\nIt wasn't one of ours.\n\nLikely it belonged to one of the Wildhammer. I know that Kurdran wanted to establish contact with the lost Wildhammer clans as one of his primary objectives after taking the beach. \n\nI can't spare any more of my men to scout it out, but I can spare you. Find that downed Wildhammer!", completion = "Aw dang crap it all. You're just an Alliance {class}. I was hoping for a rescue.", objectives = "Locate Thordun Hammerblow, a downed Wildhammer gryphon-rider, at the Twilight Shores in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27515] = { id = 27515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roots'll Do 'Er", description = "Look here, mate. She's on her last legs! If me bird dies, I'm as good as worthless.\n\nSo make yerself useful. Here on the peninsula you can dig up thorny stankroots. Oh the smell will knock you on yer patoot but steeped in water it'll boil up into a right powerful cure-all.\n\nGather some while I defend me bird. An' hurry! You Alliance wanks don't have a reputation for timely intervention, right?", progress = "Didja get me roots, {class}? Well?", completion = "Oh, that's the stuff all right! Hope ya didn't eat any. Gives you the cramps something awful but it does wonders for birds.", objectives = "Gather 8 Thorny Stankroots from the Twilight Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27516] = { id = 27516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings Over Highbank", description = "Aye, look! I think she's perkin' up already.\n\nOkay <Mr./Miss> Alliance fancy-pants {class}. Is that your base I see on the shore? \"Highbank\" you say. Can me and my bird hunker down there until she's better?\n\nHop on! We'll fly together back to Highbank!", completion = "Well done, {name}! Aiding that downed gryphon-rider has given us our first contact with the old Wildhammer clans. We'll be able to find out who's still left, and in what numbers.\n\nOur campaign is looking up!", objectives = "Speak with Thordun Hammerblow and fly together back to Highbank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27517] = { id = 27517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nYou can never have too much of this stuff!\n\nYou resolve to scrounging every scrap of it you can find from the skeletons here.", progress = "What have you found, {name}?", completion = "Ahh, rope! Thanks, kid.\n\nSomething tells me I'm going to need this.", objectives = "Collect 6 Rope Pieces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27518] = { id = 27518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transdimensional Warfare: Chapter III", description = "<Sylvanas speaks directly through you.>\n\nYou must find the being responsible for keeping this dimensional pocket active. Likely that fool, Ataeric... Search the compound for him. Should you find him, do what you must to stop him from channeling his magic. He is undoubtedly protected by a powerful arcane shield, and will send minions of arcane energy after you.  Defeat the minions while they are near him to unleash their energies.  No mage can handle that much power!", completion = "Had I not witnessed what you did with my own eyes I would not have believed it, {name}. Now, with the Ambermill magi on our side, there is but one thing left to do before we retake Gilneas and send those Alliance dogs running for Stormwind.", objectives = "Overload Archmage Ataeric with arcane power to bring down the Transdimensional Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27519] = { id = 27519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Choking Sands", description = "No... it cannot be.\n\nOrsis is all but buried beneath the desert sands.\n\nThe enemy will pay for this.\n\nBut first we must aid my people.  Quick, {name}.  We do not have much time before the last of my brethren are buried alive!", completion = "I thank you, {name}.  Orsis was punished for not joining the forces of Deathwing.\n\nPrince Nadun has offered my people refuge in his city.  I must go there and tend the survivors.", objectives = "Rescue 8 Orsis Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27520] = { id = 27520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minions of Al'Akir", description = "Al'Akir has sent his minions to do Deathwing's bidding.\n\nThe message is clear.  We join them or they destroy us.\n\nI do not know much about you, {race}.  But I do know this.  If you prove yourself to be an enemy of Al'Akir's, your aid will not go unnoticed.\n\nWhat do you say, {class}?", completion = "You continue to prove to be a valuable ally, {name}.", objectives = "Slay 6 Scions of Al'Akir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27521] = { id = 27521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wretched Hive of Scum and Villainy", description = "{race}... please, I ask your help.\n\nSomething's happened to my people.  Our commander, Ranger Lord Hawkspear, came upon an item of magical energy, and my friends, my family... they succumbed to its seductive power.\n\nThey're corrupted, {race}.  All of them.\n\nMy Ellaria wouldn't want to live like that, nor would any of my brothers.  Please, put them out of their misery.  Quel'lithien Lodge is not far; it's just up the hill, to the northwest.", progress = "You have no idea how difficult it was for me to pull myself away, {race}.  I nearly ended up one of them.", completion = "Do not feel sorry for me.  Those were my friends that you saw at Quel'lithien Lodge, but they were already as good as dead.", objectives = "Kill 9 Wretched at Quel'lithien Lodge in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27522] = { id = 27522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat it Out of Them", description = "We paladins are normally taught to exercise judgment and control when dealing with foes, but this is an emergency, and I never paid too much attention to my trainers anyhow.\n\nI'm going to head into the Plaguewood and find out what I can about Giddy.  You deal with the Scourge just to our northeast, on the other side of this tower.  The undead don't fear death, but if you beat them enough, their tongues might slip, and we may get some clues to Gidwin's location.", completion = "It sounds like you were successful.  Hopefully this is enough information to find Gidwin.", objectives = "Beat down at least 6 Scourge Siege Engineers to discover details about Gidwin's location and his captor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27523] = { id = 27523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwing, Oh How I Hate Thee...", description = "I have seen many things in my day, {race}.  The peaks of Mt. Hyjal... the oddities of Outland... a wall of Scourge soldiers, proceeding into war.  But I have never seen a bat as big, or as shockingly white, as Duskwing.\n\nHow he taunts me from his roost!\n\nThis albino demon bat circles to the southwest of here, due north of Blackwood Lake.  Track him down and destroy him.  If he flies too high for you to reach, use my flare to get his attention.", progress = "I hope you've done away with that creature.", completion = "Excellent work.  I can now continue my work without the distractions of that great white beast.\n\nI shall fashion this fur into something you can use.", objectives = "Obtain a Patch of Duskwing's Fur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27524] = { id = 27524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Fury", description = "Tarenar wasn't joking when he said that he didn't care about judgment and caution.  He nearly took off that high elf's head as he ran into the Plaguewood, looking for Gidwin.  You should go after him.\n\nThe Plaguewood is a big place, {name}.  Good luck.  I hope to see you <boys/three> come out of the woods in one piece.", completion = "I haven't found anything but brainless undead, and plenty of them.  I was just about to kill my way into Stratholme when you arrived.\n\nDid you have any more success?", objectives = "Find Tarenar Sunstrike within the Plaguewood in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27525] = { id = 27525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of Stratholme", description = "Baroness Anastar holds him?  Here in the Plaguewood?\n\nThe Plaguewood is a big place... but we will find him.  We WILL find Gidwin.\n\nImmediately to our east and our west are a pair of necropoli that flank the entrance to Stratholme.  Inside them, you will find a pair of death knights - Rivendare's lieutenants.  I doubt either would have any use for a paladin hostage, but perhaps they will have some information on his location.", progress = "We're getting close.  I only hope it's not too late.", completion = "We've got to keep moving!  We're getting so very close!", objectives = "Kill Omasum Blighthoof and Karthis Darkrune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27526] = { id = 27526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin's Fate Revealed", description = "Quickly - find an entrance to the slaughterhouse to our south.  I will meet you on the inside.\n\nBe ready for a fight!", completion = "You have no idea how happy I am to see you two!  You're a sight for sore eyes... sore eyes that have been starin' through a banshee for far too long now.\n\nI'm sorry for causing so much trouble.  Will you take me back to the caravan?", objectives = "Search for Gidwin Goldbraids within the slaughterhouse in central Plaguewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27527] = { id = 27527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey's End", description = "I've had just about enough of the funk of this place.  Undead stink is bad enough, and then you add mushrooms to the mix?  I hate mushrooms!\n\nI'm going to head back to Light's Hope Chapel, {name}... and I'm taking Tarenar and Fiona with me.  I think we've all earned a well-deserved break.\n\nLet me give you this.  It's my hearthstone - you can use it to travel instantly back to Light's Hope.  I won't need it - I'm going to be riding in the caravan.\n\nIn the FRONT SEAT.", completion = "You've been more help than anyone expected of you, {name}.  The doors of my caravan are always open to you.\n\nThe boys and I have even put together a little something special for you.  Here, take your pick!", objectives = "Speak with Fiona at Light's Hope Chapel in Eastern Plaguelands.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27528] = { id = 27528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourged Mass", description = "You can't just kill the Scourge.  They will come back.  You must destroy the vile matter that makes up their being... and even then, they may come back as spectres.\n\nFew undead use up as much mass as the lumbering abominations.  Kill them, then burn their bodies.  You will find them all over the Plaguewood.\n\nNever let your rage dissipate, {race}.  Remember: these abominations are sewn together from the bodies of good people.  Their crime is that they exist.", completion = "A blessed fire cleanses even the most corrupt of flesh.\n\nThey stood no chance in the face of the Light.", objectives = "Kill 8 Overstuffed Golems, then use the Crusader's Torch on their corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27529] = { id = 27529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenders of Darrowshire", description = "The battle of Darrowshire was one of the many tragedies that we humans suffered at the hands of the Scourge.  Its effects are still felt even today.\n\nMany of the town's valiant defenders now roam again as the ghastly servants of the Scourge.  We will end their misery.\n\nHunt cannibal ghouls here within the Plaguewood.  Many of these fiends were once the good folk of Darrowshire, and destroying their forms now will set their souls free.", completion = "It is good to hear you found the tortured souls of my brethren and freed them.  I find my strength renewed, knowing at least some of the defenders of Darrowshire no longer wallow in the vile subservience of the Scourge.", objectives = "Free 8 Darrowshire Spirits from the bodies of Cannibal Ghouls, then speak with them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27530] = { id = 27530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpsebeasts", description = "To the south, gutless cultists are focused on a grim task: re-animating enormous hunks of flesh, to create giants known as corpsebeasts.  Luckily for us, these giants are still lifeless and weak.\n\nTake this charm - using it will place a font of holy energy on the ground.  If you can manage to place three of them near one of the corpsebeasts that the cultists are reanimating, the holy energy should overload it, destroying its body forever.", completion = "You are a true Champion of the Light, {name}.  I wish you luck in your future endeavors, wherever they might take you.\n\nIf you need anything in the future, you can always find me here - knee-deep in the corpses of the slain.", objectives = "Destroy the hulks of three Corpsebeasts by placing three or more Argent Lightwells next to them. You cannot place Argent Lightwells while in combat, and you may not place them within ten yards of one another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27531] = { id = 27531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counter-Plague Research", description = "I once worked for the so-called \"Banshee-Queen\", Sylvanas, as an apothecary.  I used to admire her, but something's changed within her.  She's not herself anymore.\n\nI broke my vows with the Forsaken and joined the Crusade.  Now, I use my knowledge of alchemy to seek a counter-plague agent.  And the Plaguewood is the perfect place to do so.\n\nI need to resupply a few reagents, any of which can be found within the Plaguewood.  I'll pay you if you can find any of these items.", progress = "You got the stuff?", completion = "I love the smell of fresh foot scrapings, don't you?\n\nIf we're going to find a cure to the plague, we need to get creative with our ingredients.  Now, if you don't mind, I'm going to get back to work.", objectives = "Obtain 20 Rotberries, 5 Disembodied Arms, and 1 pile of Flesh Giant Foot Scrapings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27532] = { id = 27532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plaguewood Tower", description = "With the recent, unfortunate developments involving Gidwin, it might not be wise for a man my age to take the dangerous trip through the Plaguewood.  This is fine - I can visit the Plaguewood Tower on my next trip around the loop.\n\nI do, however, have a delivery that I need to get to Judkins.  You are younger than I, and stronger in combat.  Will you take this delivery to him?", progress = "Highbeacon's Parcel... is Argus safe?  Did something happen?", completion = "Whew.  Every time Argus comes plodding through that Plaguewood, I fear it to be his last.  It's good to see that he's wise enough to send a youngblood like you in his stead.", objectives = "Bring Highbeacon's Parcel to Argent Apothecary Judkins at Plaguewood Tower in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27533] = { id = 27533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Worse Than Butchery", description = "The people of Terrordale, they were sick, then they turned bad.  Definitely not good times.\n\nThe pigs, though... they also got sick!  What did pigs do to deserve to get sick?  Hah hah hah!  Nothing!\n\nPeople I can forget about, but the bad pigs still make me sad.  If you kill them, though... I might get happy.", progress = "I cry for the poor pigs.", completion = "I see them!  Can you?  The little pig spirits, on their way to the great sty in the sky...", objectives = "Kill 9 Plagued Swine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27534] = { id = 27534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Receipt Book", description = "I'm ready for business!  What do you want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, {name}!  Stupendous!  Insanely good, I say!", objectives = "Get Augustus' Receipt Book from the inn in Terrordale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27535] = { id = 27535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Little Touched", description = "I like to check in on Augustus in Terrordale every once in a while, just to make sure he's alright.  Some of us undead cope with the plague better than others, I suppose.\n\nTerrordale is west of here.  Would you mind checking in on him for me?", completion = "You've come to the right place, mister!  No place better than Terrordale, yes siree, that's right!  The jewel of Lordaeron!", objectives = "Speak with Augustus the Touched in Terrordale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27536] = { id = 27536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mostly Harmless", description = "Here's another favor you can do for me, pal.\n\nWe had a whole shipment of Landmines come in from Booty Bay just the other day. But someone stole the whole lot of 'em in the night!\n\nWhoever it was must be sloppy, because they dropped them all over the swamp to the east. No goblin I know would be that careless.\n\nI need you to go gather those landmines up for me. I'm sure they're perfectly safe and disarmed. Every single one. Yup.", progress = "Hey, you get those things I asked you about?", completion = "What did I tell you, eh? Perfectly safe!\n\nI'll see about getting some of these over to to your friends, {name}. At a discount.", objectives = "Collect 8 Disarmed Land Mines from the Sorrowmurk to the east of Bogpaddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27537] = { id = 27537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Any Portal in a Storm", description = "Our friends in the Earthen Ring have been trying to open portals back to Stormwind, with no luck. But Thordun here tells me he might just have the key.\n\nThe crazed water elementals in the nearby Verrall River Delta have been sent into a frenzy. Thordun tells me we can channel their energy into a portal.\n\nI don't understand all this elemental-claptrap, but I understand one thing: killin' elementals and takin' their whirlpool cores. Deliver them to Talaa in the courtyard!", progress = "Hello, {class}. Kurdran tells me you've got a solution to getting this portal opened?", completion = "My word, {name}. These elemental energies are so powerful, so chaotic - no wonder the Twilight's Hammer has chosen to build their stronghold here!\n\nI should be able to channel these energies into something more benign and productive though. Let's give it a try...", objectives = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27538] = { id = 27538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Poultice", description = "Are you goin' by way of the Verrall river delta? I've got a tip that'll help your men here... and my bird!\n\nWhen water elementals carve their way through rock, they create a peculiar kind of muck. It dries hard as stone but carries with it the rejuvenating power of water. You make a cast out of that muck and broken bones knit together like iron.\n\nBring some of that muck to Talaa, your shaman downstairs. She'll know what to do with it!", progress = "What is this I keep hearing about the muck of the Verrall River?", completion = "Oh... mud. You brought me mud?\n\nWow - this stuff oozes with power! I see what Thordun was saying, now. I'll distribute this to all of the healers. Our wounded will be on their feet in no time!", objectives = "Collect 10 piles of Verrall River Muck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27539] = { id = 27539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Add 'em to the Pile", description = "I've been collecting the skulls of the skeletons I defeat.  I've amassed a small pile of them.\n\nIf you come across any skulls, you are welcome to add them to my pile.  The huge pile of skulls seems to keep the waves of undead at bay and... well... it also just makes me happy to look at it.", progress = "You seem to have your hands full.  Are those skulls I see?", completion = "May my pile never stop growing.", objectives = "Obtain 16 Stinking Skulls from Cursed Mages and Scourge Soldiers in the Plaguewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27540] = { id = 27540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wildhammer", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns.  The Earthen Ring struggles to understand what is going on.  We've been fortunate to gain assistance from the Wildhammer shamans.\n\nGavan Grayfeather is in Stormwind Keep to help coordinate our efforts with the various faction leaders.  Speak to him and see what you may learn about these events, {name}.", completion = "Well met, {class}.  I am Gavan Grayfeather, emissary of the Wildhammer shaman.\n\nThere is much work to be done.  The leaders fear for their citizens, as many have turned to cults.  We shaman are concerned with the elemental unrest.\n\nOur advice to you, {class}, is to be vigilant.  Help where you can, be it calming the people or putting the elementals at rest.  There is plenty to do.", objectives = "Speak to Gavan Grayfeather in Stormwind Keep.No doubt you've felt the earthquakes. You may even have seen elementals attacking the lands or towns. The Earthen Ring struggles to understand what is going on. We've been fortunate to gain assistance from the Wildhammer shamans.\n\nGavan Grayfeather is in Stormwind Keep to help coordinate our efforts with the various faction leaders. Speak to him and see what you may learn about these events, {name}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27541] = { id = 27541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons From the Past", description = "This unfortunate explorer has clearly suffered a bit of bad luck in the recent past.\n\nPrudence dictates that you perform the unenviable task of searching the corpse for clues that might shed light on your surroundings...", progress = "Any news, {name}?", completion = "Odd...\n\nIt looks as if someone used gemstones as lenses.\n\nI should be able to fix them without too much trouble.", objectives = "Acquire the Broken Goggles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27542] = { id = 27542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Battlefront", objectives = "The hour of victory approaches, {name}. Godfrey has devised a plan to decimate our enemies. I am sending you into the field with him and his men to bring the rebel insurgents to their knees and seal the fate of the Alliance filth encroaching upon our lands.\n\nOur final march begins when you are ready.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27544] = { id = 27544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Tenacity", description = "Those druids never give up, I swear.  I'd given up on the Plaguelands years ago, but the Cenarion Circle folks keep telling me that the land is not beyond hope.\n\nThe most recent visitor was a night elf, on her way to the Fungal Vale, to the north.  She told me that these lands will make a full recovery, if we try hard enough.  I'm not sure I believe her.\n\nDo you buy this drivel?  Maybe you and her should talk.  She should still be up there.", completion = "I suppose I had better work on my stealth, if you were able to find me.\n\nAre you interested in helping me heal the Plaguelands?", objectives = "Speak with Rayne near the entrance to the Fungal Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27545] = { id = 27545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way is Open", description = "My fellow Shaman and I will stay here to keep the portal open.\n\nYou should go upstairs and notify Kurdran that the work here is done. It'll please him to hear some good news for once.", completion = "Ho! I knew you were a {class} I could count on, {name}. Use that portal anytime you need to get from Stormwind back to the Highlands.\n\nNow then, time to get to business. We need to locate and unite the lost Wildhammer clans scattered around the Highlands. Talking with Thordun here is a good start!", objectives = "Speak with Kurdran Wildhammer at Highbank in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27546] = { id = 27546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Captain Anton", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here.  Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", completion = "King's honor, {class}.  I am Captain Anton.  I am leading the investigation into the cultists that have appeared in Stormwind.", objectives = "Speak with Captain Anton in Stormwind Keep.No doubt you've felt the earthquakes. You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here. Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27547] = { id = 27547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of No Consequence", description = "Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops.\n\nThe Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands.\n\nLet's get this nonsense over with, {name}. Pyrewood is directly southwest of the Forsaken Front.", progress = "The sooner we rescue survivors the sooner we can burn down the whole of Pyrewood.", completion = "What happened here today is between us. Say a word to anyone and you will find yourself in a corpse pit next to these poor fools.", objectives = "Rescue 8 Cowering Troopers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27548] = { id = 27548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons in Fear", description = "Our enemies are becoming smarter - adapting to our tactics. Recently an attack was made upon Pyrewood Village, southwest of here. Our troops occupying the town were decimated, of course, but what made the attack especially interesting was the racial composition of the attacking force. No humans were used.\n\n<Walden laughs.>\n\nRightfully, they fear being reanimated as Forsaken.\n\nLet us teach the non-humans a lesson in fear. Together we will show them what happens to corpses that we cannot use.", progress = "Pyrewood Village must be reduced to ashes and our enemies slain!", completion = "I suspect we'll see fewer humans at the Battlefront. The risk for these cowards is too great.", objectives = "Kill 12 7th Legion Scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27549] = { id = 27549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Light of the Stars", description = "Look at this, {name}.\n\n<Harrison holds up the dead scout's goggles.>\n\nI tightened the clamp in the middle and crimped the wires on the edges. They may not be the most comfortable, but they should hold together.\n\nIf I've translated your tablets correctly, there's something hidden here - a final piece to our puzzle.\n\nI hope your spectacles hold the key.\n\nLet me know what you find!", progress = "So?\n\nFind anything interesting?", completion = "Well, kid, it looks like you've done it again.\n\n<Harrison points to an image on the tablets.>\n\nThis starlight is exactly what we were missing.\n\nNow we can get to work!", objectives = "Collect 7 Suspended Starlight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27550] = { id = 27550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrewood's Fall", description = "The attacks against our front are a distraction. With our attention turned towards the worgen onslaught, the Alliance has managed to take Pyrewood Village from our occupying forces.\n\n<Godfrey hands you a bundle of torches.>\n\nIt must be purged.\n\nWith these torches we will burn Pyrewood Village to the ground, leaving only ashes for the enemy to hide behind.\n\nLet us not waste another minute. Pyrewood Village is located southwest of the Forsaken Front. Lead us there, {name}.", progress = "I feel no remorse.", completion = "The part of me that was Gilnean died at Tempest's Reach. Only vengeance remains, {name}. To that end, we have work to do. Spare me your pointless queries.", objectives = "Use the Bundle of Torches to torch the Pyrewood Town Hall, Pyrewood Inn and Pyrewood Chapel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27551] = { id = 27551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Baroness' Missive", description = "The note is from Baroness Anastari, and it describes a ritual that is about to happen in the Plaguewood's central slaughterhouse - just south of where Tarenar is at.  This could be where they're holding Gidwin!\n\nTarenar will want to know about this... and quickly, before it's too late!", progress = "What?  Did you find something?", completion = "This is it!  If this missive is to be believed, then he's literally right over this hill!\n\nWhat are we waiting for, {name}?", objectives = "Bring the Baroness' Missive to Tarenar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27555] = { id = 27555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiona's Lucky Charm", objectives = "Fiona has left some of her charms inside the caravan.\n\nAs a trader, she seems to be pretty good with money.  Maybe carrying one of her charms will help out with your finances.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27556] = { id = 27556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin's Weapon Oil", objectives = "Gidwin has left several bottles of weapon oil inside the caravan.\n\nHe seems to be quite a fierce combatant up close.  Perhaps his weapon oil will help you out as well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27557] = { id = 27557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar's Talisman", objectives = "Tarenar has laid a few holy talismans inside the caravan.  They appear to be unused.\n\nThey appear to be magical in nature.  If Tarenar isn't using them, what's the harm in borrowing one for a while?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27558] = { id = 27558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamela's Doll", objectives = "You see a small doll sitting in the back corner of the caravan.\n\nTarenar tells you that it must belong to Gidwin, and Gidwin says that it's probably Tarenar's.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27559] = { id = 27559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vex'tul's Armbands", objectives = "Vex'tul has left some of his wrappings within the caravan.  Surprisingly, he was courteous enough to keep them folded and separate from everyone else's belongings.\n\nVex'tul values strength over everything else.  Leaning in close, you can sense some of his residual strength emanating from within these armbands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27560] = { id = 27560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argus' Journal", objectives = "You see a trail-worn journal inside the caravan.  Judging by the Argent Crusade emblem on its spine, it must belong to Argus.\n\nWritten within the journal are several accounts of Argus' experiences during his tenure in the Crusade.  It should prove to be an interesting read while on the road.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27561] = { id = 27561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rimblat's Stone", objectives = "You notice a small heap of stones within the caravan.\n\nThey do not appear out-of-the-ordinary, yet one of them attracts your attention.  You sense a warmth coming from within it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27562] = { id = 27562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beezil's Cog", objectives = "It looks like Beezil has already made himself comfortable, and has stuffed several peculiar gizmos into the caravan.\n\nMost of them seem too impractical or dangerous to take with you.  One small cogwheel, however, looks to be fairly well-crafted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27564] = { id = 27564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of the Redoubt", description = "Calen sent word - the Twilight are within the redoubt!\n\nIf there will ever be a time when you can earn his favor, this is it!", completion = "I hope you're as tough as your gear suggests. The Twilight's Hammer have made their way within the redoubt somehow and I need someone to hunt them down.", objectives = "Speak to Calen in the Vermillion Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27565] = { id = 27565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Prison", description = "We've managed to infiltrate the Dark Iron Prison!\n\nWell...we may have, anyway.\n\nKevin Dawson had the...honor...of seeing what was going on over there, and we haven't heard back from him since. You look like the type that doesn't like to die, you should go see if he's ok!\n\nHe's supposed to be inside the hall on the south end of the cavern ahead...though something tells me he may not have made it quite that far.", completion = "I don't know how I'm still alive. The patrols keep walking past me like I'm not even here.\n\n...Am I dead, {class}?", objectives = "Find Kevin Dawson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27566] = { id = 27566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering in Outland", description = "Greetings, {class}.  The elements have grown more restless and we seem to be making little progress to a solution for this problem.  Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with Gavan Grayfeather, he will surely have some task for you.", completion = "It is good to see you, {name}.  Here at the Throne of Elements we may be able to uncover what ails Azeroth.", objectives = "Speak with Gavan Grayfeather at the Throne of Elements in Nagrand.Greetings, {class}. The elements have grown more restless and we seem to be making little progress to a solution for this problem. Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with Gavan Grayfeather, he will surely have some task for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27567] = { id = 27567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight?! No!", description = "This is a little hard to believe, but there are Twilight's Hammer members here in Blackrock Depths! I don't know how many there are crawling throughout this place, but I did hear that their lead interrogator, Gerstahn, is in this hallway.\n\nI don't know what they're here torturing for, but maybe you can find out by confronting Gerstahn?", progress = "Go! Go! Go!", completion = "I see...she did not cooperate. Hopefully we can still stop them before something else terrible happens.", objectives = "\"Interrogate\" High Interrogator Gerstahn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27568] = { id = 27568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shadowforge City", description = "Can ye keep a secret? I have a secret tae share with ye if ye can.\n\nEverybody here is CRAZY!!!\n\nThere's goblins over there, Dark Irons right over there, and a giant living fire thing right past this gate! An' that's just what I see in this little cave!\n\nAnd ye! What're ye doin' here!?\n\nOh, I see. Winky sent ye, did he? Sent ye tae talk t' Prospector Seymour, past this gate and t' the right, did he? Well go! Oralius doesn't even care!\n\n...I'll GET YOU FOR THIS WINKY!!!\n\n<Oralius begins to sob.>", completion = "I would stay away from Oralius. Far, far, far away. He isn't quite right in the head.\n\nNow, let's get onto business!", objectives = "Speak to Prospector Seymour.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27569] = { id = 27569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Tacticians", description = "General Angerforge and Golem Lord Argelmach lead the Dark Iron armies and their golems against us. If we are to overcome them, the two must be slain.\n\nGo through this door and unlock The Shadowforge Lock, which separates the East and West Garrisons. Then, follow the stairs and keep to the left at the top until you reach the West Garrison. It is there you will find the General and Golem Lord.\n\nKeep your wits about you, they are both well-seasoned combatants. Find Mayara Brightwing should you succeed.", completion = "I'm sure you are up to the task I have for you if you've made it this far in one piece.\n\n<Mayara Brightwing lowers her voice to a whisper.>\n\nBetween you and me, you may want to enjoy yourself in the Grim Guzzler while you're there. It could be the last drink you ever have.", objectives = "Kill General Angerforge and Golem Lord Argelmach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27570] = { id = 27570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Situation So Far", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns.  The Earthen Ring struggles to understand what is going on.  We've been fortunate to have one of the greatest shaman as our Warchief.\n\nThrall has been consulting with his advisors, and we don't want to interrupt his council.  But perhaps our brother, Gotura Fourwinds, has learned of Thrall's plans.", completion = "Greetings, {class}.  The situation here is tense.  The elements are restless and the people are scared and confused.  The Warchief is trying to find a semblance of balance between leading the people and protecting Azeroth.  Though it seems he will soon be leaving us to travel to Nagrand and gain insight about the elementals.\n\nRegardless of the Warchief's choice, we still must do what we can.  Help calm the populace, scour the lands for rogue elementals.  These tasks will surely help our cause.", objectives = "Speak with Gotura Fourwinds in Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27571] = { id = 27571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grim Guzzler", description = "Some say that the Grim Guzzler is the secret to the Dark Iron war effort. Their warriors recharge there and emerge thirsty for another innocent soul. I think we can seriously hinder them by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Orfus when you're done.", progress = "Hurry, please. Time is not a luxury we currently have.", completion = "The Dark Irons took our Thunderbrew. I'll never let them live after that. I'd kill 'em all myself if I could!\n\nHowever, look ahead and you'll see we have slightly more dire matters to attend to at the moment.", objectives = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27572] = { id = 27572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering in Outland", description = "Greetings, {class}.  The elements have grown more restless and we seem to be making little progress to a solution for this problem.  Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with our Warchief, he will surely have some task for you.", completion = "It is good to see you, {class}.  Here at the Throne of Elements we may be able to uncover what ails Azeroth.", objectives = "Speak with Thrall at the Throne of Elements in Nagrand.Greetings, {class}. The elements have grown more restless and we seem to be making little progress to a solution for this problem. Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with our Warchief, he will surely have some task for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27573] = { id = 27573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Pact", description = "Ahead is the creature known only as Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them, so that this nation may perhaps one day be redeemed.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this.", objectives = "Kill Ambassador Flamelash and Doom'rel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27574] = { id = 27574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Never Forget a Face", description = "You have discovered a partially digested head. Lord Godfrey perks up when he sees it. Perhaps you should give it to him.", progress = "I never forget a face!", completion = "I know that face, {name}. This head belongs to a former Gilnean known as Sean Dempsey. He was imprisoned with Crowley before the great outbreak.\n\n\n\nI wonder if it would be possible to put him back together. The rest of him must be in the belly of these crocolisks.", objectives = "Give the Partially Digested Head to Lord Godfrey in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27575] = { id = 27575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Belly of the Beast", description = "I think we can rebuild him. Perhaps if we put him back together he can give us information about Crowley.\n\nWe must kill every crocolisk in this marsh until we find the rest of Sean Dempsey's body! From the belly of the beast this man will be reborn!", progress = "At the very least we'll have some crocolisk hides to make fancy shoes out of.", completion = "Now let's see if I can do this.\n\n<Godfrey starts mumbling under his breath.>\n\n...leg bone connects to the thigh bone...\n\n...arm bone to torso...\n\n...sprinkle on a little Forsaken necromancy...\n\nTA-DA!", objectives = "Recover Dempsey's Torso, Dempsey's Appendages and Dempsey's Giblets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27576] = { id = 27576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patchwork Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Patch in Dragonmaw Pass, in the canyon below us to the south.", completion = "You got the dragons in the game! Good on you.\n\nWe'd already laid out plans for our ambush by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nIt's not too late for you to join in on the fun though. We saved some for you.", objectives = "Speak to Patch in Dragowmaw Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27577] = { id = 27577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7th Legion Battle Plans", description = "While destroying Pyrewood will certainly garner us an advantage over the Alliance upon the field of battle, our true purpose here is to leave them crippled.\n\nSouthwest of here, near the Greymane Wall, lies the 7th Legion Base Camp. We must search the base camp for battle plans. With the 7th Legion battle plans we will be able to pinpoint all Alliance troop advancement in Silverpine Forest.", progress = "Search every filthy dwarven corpse.", completion = "<Walden flips through the battle plan.>\n\nIt looks like the reinforcements from the ships in Gilneas are marching soon. Crowley and Bloodfang have set up an encampment to the southeast for the Gilneas Liberation front.", objectives = "Recover the 7th Legion Battle Plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27578] = { id = 27578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan's Fruition", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", progress = "If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", completion = "You've done it! You've actually done it! Morgan's years of planning and waiting have finally come to fruition.\n\nShe may have lost her land and family when Ragnaros tore this land asunder, but with the Dark Iron crippled we'll be able to safely build a new kingdom of our own in the Burning Steppes. Not even the Firelord himself will be able to breech the capital's walls!\n\nMake sure you come back someday when we've finished, you'll be our guest of the highest honor. I thank you with all my heart, {name}.", objectives = "Kill Emperor Dagran Thaurissan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27579] = { id = 27579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Prison", description = "Da Twilight's Hammer be here for some reason. We don't know why, but Thal'trak be lettin' you in on a lil' secret of ours - da rogue Lexlort waits outside da hall where High Interrogator Gerstahn be so he can kill her if he gets da chance.\n\nShe's too smart for dat, though, so you gonna go in an' do it, ya? Go talk to Lexlort and let him know. I'm sure he be ok with it.", completion = "Get over here. If you blow my cover, I swear to the Warchief I'll kill you where you stand.", objectives = "Find Lexlort.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27580] = { id = 27580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing Discord", description = "The Alliance reinforcements have established a foothold in the southwest region of Silverpine called 7th Legion Base Camp. Our primary goal at the base camp is to sow discord amongst the troops. This is a lightning fast assassination mission to kill their field commander, General Marstone. His death won't stop the Alliance advance, but it will certainly soften their ranks.", progress = "Marstone is a decorated field general. He will not go down easy.", completion = "The rest of the Alliance fleet will arrive shortly, only to find their base camp decimated. Now for the second and most important part of our battle plan.", objectives = "Assassinate General Marstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27581] = { id = 27581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight?! No!", description = "Gerstahn is too heavily guarded and too smart to leave her post, so I'm not going to kill her.\n\nYou are.\n\nI'll throw in a little something I picked up off of a guard to make it worth your while.", progress = "Does it look like I want to be waiting her any longer than is necessary?", completion = "The Twilight's Hammer's presence only complicates our mission here further, but you've done your part for now.  You've earned a reward for your efforts...and some rest. Let's get out of here.", objectives = "Kill High Interrogator Gerstahn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27582] = { id = 27582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating Shadowforge City", description = "We're fighting a losing battle right now, I'm afraid. The Dark Irons would be difficult to defeat on their own, but their elemental allies have given them new bleeding edge warriors that we simply can't compete with.\n\nI need you to help us infiltrate their domain and kill as many of their vital leaders as possible. Hopefully that will shock their forces and turn the tide in our favor. Report to Razal'blade for further instruction. He's stationed beyond this gate and to the right.", completion = "Beyond this door lies the commander of the Dark Iron Army, surrounded by trained soldiers. Are you up for a little killing?", objectives = "Speak to Razal'blade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27583] = { id = 27583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Flank", description = "I have ordered a defensive perimeter set up on our northern coast, at the Slithering Cove. Our scouts reported that the naga were trying to make landfall there.\n\nGralok is in charge of the operation - report to him and secure that beach!", completion = "Warlord Zaela sent you? Good.\n\nIf you Horde are as strong as your Warchief promised, I expect to see some bloodshed on these shores.", objectives = "Report to Gralok at the Slithering Cove in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27584] = { id = 27584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood in the Surf", description = "These naga scum think to move upriver to reinforce the Bastion of Twilight. We will RIP off their fish heads and PULL OUT their SPINES.\n\n<Gralok drives his broadsword into the dirt.>\n\nDestroy the Blackscale!", progress = "After the battle we will mount their heads on pikes and build a wall all along the beach. THAT will show these belly-crawling SNAKES who owns the Highlands.", completion = "<Gralok sizes you up.>\n\nYou're a true fighter, {name}. I liked watching you work. Perhaps the Dragonmaw really DO belong in your Horde.", objectives = "Slay any combination of 15 Blackscale Raiders or Blackscale Mistresses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27585] = { id = 27585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The 109th Division", description = "General Angerforge and Golem Lord Argelmach are directly responsible for the horrific slaughter of the 109th Division of the Kargath Expeditionary Force. There were a lot of good trolls and orcs in that division, many of them my close friends.\n\nWell, young {race}, it's time for our fallen brothers to at last have their revenge.\n\nUnlock The Shadowforge Lock, go up the stairs and bear left until you reach the West Garrison. Kill Angerforge and Argelmach, and don't you dare show them any mercy.", progress = "I'm quite surprised to see you here! You'll be very useful indeed.", completion = "Up ahead is the Grim Guzzler. A disgusting bar full of all our enemies, intoxicated and therefore unfit for proper battle.\n\n<Hierophant Theodora Mulvadania grins.>\n\nRipe for the slaughter.", objectives = "Kill General Angerforge and Golem Lord Argelmach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27586] = { id = 27586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shells on the Sea Shore", description = "I salvaged these mortars from the wreck of our airship when she detonated above Dragonmaw Port. But ammunition is in short supply!\n\nWhile you're running along the beach, do me a favor and pick up any unexploded mortar shells you find.\n\nUnexploded shells are the best kind - you never know WHEN they're going to go off. Perfect for surprising an enemy!", progress = "Do you have the shells? Hand them here!\n\n...Gently!", completion = "Oh yeah. YEAH! These are DEFINITELY going to kill somebody.\n\nProbably naga.", objectives = "Gather 8 Unexploded Mortar Shells along the beach at Slithering Cove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27587] = { id = 27587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maliciously Delicious", description = "You know, I've got a problem you might be able to help me out with, here.\n\nSee, in addition to the fine pursuit of arms dealing, I'm trying to liven up the entertainment here in Bogpaddle. Apparently there's a bunch of these makrura things in the north waters that don't take kindly to the wild beach parties we've been throwing.\n\nJoke's on them. I'm not gonna be pushed around by giant lobsters; they're my next source of revenue! You bring me some of their tails and we'll turn a problem into profit.", progress = "You got those tails? Don't be tryin' to push no hacked-up ones on me!", completion = "I can see it now: our own famous Bogpaddle Lobster-Poppers! Made fresh from the sea! Oh, it's like this stuff writes itself...\n\nYour help is very much appreciated, my friend. I'll start seeing if I can't cut your people a favorable arrangement, eh?", objectives = "Collect 6 Intact Swampshore Tails from Swampshore Makrura.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27588] = { id = 27588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27589] = { id = 27589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grim Guzzler", description = "Everyone inside the Grim Guzzler is absolutely hammered and, therefore, easily angered. I think we can seriously hinder the Dark Irons by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Thunderheart when you're done.", progress = "Hurry, please. Time is not a luxury we currently have.", completion = "I hear quite the commotion coming from the Grim Guzzler. I see you've been hard at work.\n\nIf you'll direct your attention opposite me, you'll notice that we have bigger issues to worry about than toying with drunkards.", objectives = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27590] = { id = 27590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27591] = { id = 27591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Pact", description = "Inside this chamber lies Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them all, and may this unholy union cease.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this.", objectives = "Kill Ambassador Flamelash and Doom'rel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27592] = { id = 27592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drinks on the Rocks", description = "What's up, \"bro\"! We were just in the middle of our completely spontaneous beach party when something terrible happened, \"dude\"!\n\nI had a whole case of Silversnap Ice, the Baron's own drink of choice, until the silt crawlers stole them! I've never seen crawlers drink, but they took them right into the water and down the beach! We need some sort of awesome hero who can help retrieve our specifically-branded favorite beverage!\n\n<Brono stares at you a moment.>\n\nThat means you, \"brah\"!", progress = "You got the goods, \"bro\"?", completion = "Our ice-cold, refreshing Silversnap Ice! I can't thank you enough, \"dawg\", for this entirely spontaneous act of heroism!\n\nHere, have your very own bottle as a totally sincere gesture of thanks! Be sure to tell ALL YOUR FRIENDS how good it is.", objectives = "Collect 10 bottles of Stolen Silversnap Ice from Silt Crawlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27593] = { id = 27593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebirth of the K.E.F.", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", progress = "If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", completion = "A true {class} if I've ever seen one! You've done the impossible! I knew we could count on you.\n\n\n\nAnd with that, I'd like for you to be the first to know that the Kargath Expeditionary Force is now officially back in business!\n\nI extend to you my personal gratitude for your efforts here. Remember always our motto: \"First in, last out, always victorious. Remember always Kargath.\"\n\nYou are dismissed.", objectives = "Kill Emperor Dagran Thaurissan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27594] = { id = 27594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Her Majesty's Secret Service", description = "Lorna Crowley, daughter of Lord Darius Crowley, is currently at the Gilneas Liberation Front camp, located near the Greymane Wall, to the southeast.\n\nOur primary mission is to infiltrate the camp and capture her alive. The Dark Lady believes that she will be able to use Lorna as a bargaining chip against Crowley. I say we just kill her and bring her back as Forsaken, but we must do as the Dark Lady commands.\n\nWe must hurry before the rest of the Alliance forces arrive.", completion = "You have done it! Finally, everything is in place. Should Crowley not accept our terms, his daughter will be turned.", objectives = "Capture Commander Lorna Crowley and return her to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27595] = { id = 27595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet Hadassi", description = "Prophet Hadassi is the wisest and eldest member of the Orsis tribe.\n\nHe has not been accounted for and his well-being is of vital importance.\n\nGo into Orsis and find him.  A great day of reckoning will come to the Al'Akir's lackeys if he's been hurt.", completion = "Who... who are you?  Sent here... to rescue my people and fight our enemies.", objectives = "Find the Prophet Hadassi in Orsis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27596] = { id = 27596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to The Black Vault near the Hall of Crafting, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, {name}, take this as payment!", objectives = "Obtain the Heart of the Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27597] = { id = 27597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crazy Larry", description = "You're gettin' it, {name}. You scratch my back, I scratch yours. Well, more like I scratch the back of your whole army, and just a little harder than the backs of the other side! Was that too complicated?\n\nWhat I'm sayin' is, that's a lot of backs. So I'm gonna have to ask you to scratch mine a few more times. Whoever stole those landmines may have just hit our boys on the eastern shore.\n\nHead to our camp to the southeast and check on Crazy Larry; he'll fill you in when you get there.", completion = "Silversnap sent you?! I'm DOOMED!\n\nOh, he sent you to help me! That's different, haha!", objectives = "Find Crazy Larry to the southeast of Bogpaddle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27598] = { id = 27598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Gil", description = "Gilblins!\n\n<Larry stares at you silently for a while.>\n\nYou never seen a gilblin before? They're crazy! Crazier than me! I just blow stuff up for a living, these guys are WHACKED!\n\nDunno where they came from, but they're like awful fish goblins! Gills and everything! They wiped out all my men down at the beach, and they took our shipping freighter!\n\nYou gotta help! They're just down to the east, go on and get rid of those gilblins!", completion = "That'll show those fish-faced freaks! Good work!", objectives = "Slay 7 Gilblin Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27599] = { id = 27599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Take It With Them", description = "Any shipping crew I had that you don't see hanging around this camp are DEAD! Those were some fine goblins, but what's worse is they're all still out there! It's a TRAGEDY!\n\nI mean, it's a tragedy they still have all their stuff! It's horrifying to think of all the perfectly good materials and coins sitting out there in the water.\n\nHey! You can do me a favor! If you're killing gilblins out there, go get the ditty bags off my old crewmen!\n\nC'mon, they're not gonna need it anymore! Be real!", progress = "You get those ditty bags? I hope you left the goblins there!", completion = "WOW!\n\nI don't know why I said that. I'm excitable! But man, there was a lot of stuff on these guys, check it out!\n\nHere, you want this?", objectives = "Collect 6 Ditty Bags from Deceased Bogpaddle Privateers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27600] = { id = 27600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In With a Bang", description = "Our trade frigate's still all the way out there on the water, swarming with Gilblins! AHH!\n\nSorry about that. But really! We need a way to get you out there and get back our stuff. There's quality goods left on that ship! QUALITY! LIKE MY MIDDLE NAME!\n\nLucky for you, I have an idea! Head right outside the camp and check along the north wall... my son Jerry'll get you over there with our cannon! If he's been practicing, that is!", progress = "You got it? Did you get it? Did you try the cannon? You didn't explode!", completion = "My high-grade fuse! My imported blasting powder!\n\nAnd my--hello there! I'll just be taking that!\n\nThose are all worth more gold than what you're wearing, you know! Thanks for your help!", objectives = "Speak with Lil' Crazy Jerry to board the ship, then retrieve all three of Crazy Larry's important goods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27601] = { id = 27601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cities in Dust", description = "Our armies clash across the battlefield. Crowley and his forces are losing ground and they do not yet know the fate of Lorna Crowley. We will meet with Crowley and his compatriots at mid field and I will present them with terms of their surrender. They will either accept or we will kill them all and leave their cities in dust.\n\nAs my most trusted soldier, you are to stand by my side during the exchange. Tell me when you are prepared to leave.", completion = "<Lady Sylvanas Windrunner grimaces in pain.>\n\nThis... is not over. Godfrey and his traitorous allies will pay for what they have done as will the remaining Alliance forces occupying Lordaeron.\n\nOur work has only just begun.", objectives = "Accompany Lady Sylvanas Windrunner to the Battlefield and defeat the Alliance!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27602] = { id = 27602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet's Dying Words", description = "We... are... bound by oath... to protect the scepter of Orsis.\n\nListen, {class}, I don't have much time... left.\n\nFind the sacred receptacle... in the southern end of the city.\n\nDo not... let it... fall into their... hands...", completion = "Though the chest is locked, there is a plaque bearing interesting hieroglyphs above it.", objectives = "Find the Sacred Receptacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27603] = { id = 27603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sealed Gate", description = "At one end of the Dark Iron Highway stands a massive gate much like the one that protects Shadowforge City on the opposite side. However, we have no idea what's behind it!\n\nAll we know is that it's heavily guarded by Anvilrage patrols and the molten giant Bael'gar. You simply must dispose of them and see if you can pry that gate open!\n\nJust imagine what could lie behind it...there could be an entire other half of the city we never knew about! Or nothing! Who knows!\n\nThough, it's probably something...", progress = "Were you able to get past the gate? Or scale it? What's behind it???", completion = "Darn it! I simply HAVE to know what's behind that gate! This could be the discovery that makes my career, you know!\n\nHmm....maybe a couple good explosions would do the trick...", objectives = "Kill Bael'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27604] = { id = 27604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an the Prophet", description = "Jammal'an the Prophet, leader of the Atal'ai and Hakkari trolls, has obtained a small amount of Hakkar the Soulflayer's blood. They are injecting it into the green dragons to use their bodies to produce the massive quantities of blood necessary to summon Hakkar into our world.\n\nWe cannot allow this to come to pass. Slaughter Jammal'an and his priests before they get any further in their efforts!", progress = "Were you able to kill Jammal'an? I'll need proof that the deed is done.", completion = "Excellent! I suspect that without Jammal'an's leadership, the trolls will fall to infighting and Hakkar will never set his eyes upon our world.", objectives = "Obtain Jammal'an the Prophet's Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27605] = { id = 27605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus", description = "The Hakkar blood the Atal'ai have been injecting into the green dragons has had devastating effects on the dragons themselves. It appears that these dragons, former jailors of the Atal'ai, have been corrupted by its presence in their bodies and have become creatures of Nightmare.\n\nEranikus, Ysera's primary consort and lead watcher over the temple, was infused with the largest quantities of blood and has become twisted beyond imagination. After Jammal'an is dead, find Eranikus and end him.", progress = "Did you defeat Eranikus?", completion = "You only defeated Eranikus' Shade? This is most troubling...\n\nLet us hope that his full form does not still exist outside the Temple. Only Ysera herself is stronger than him in our flight.", objectives = "Kill Eranikus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27606] = { id = 27606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast Him!", description = "Let's go fishing, {name}! Now that the mortars are ready, we can take out the leader of this invasion.\n\nFathom-Lord Heth'Jatar rules over the Blackscale warrior caste. Go to the Heth'Jatari Banners just northeast of here and honk this conch shell. It's like a dog-whistle. For fish.\n\nWhen Heth'Jartar shows up, I'll order the mortars to concentrate fire. You'll see the targets of the incoming shells.\n\nLure Heth'Jatar into our mortar fire and pummel him into submission!", progress = "You want me to keep firing?\n\nI can keep firing.", completion = "Boom baby, boom!\n\nWhat? You killed the Fathom-Lord already?\n\nI suppose we should stop shelling his corpse, then.", objectives = "Blow the Heth'Jatari Conch next to a Heth'Jatari Banner. Kill Fathom-Lord Heth'Jatar. Luring him into incoming mortar fire will help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27607] = { id = 27607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Southern Flank", description = "Our new arrangement with the Horde will put my people in direct conflict with the Alliance.\n\nBring. Them. On.\n\nAs we speak, the Alliance moves up the peninsula to threaten Dragonmaw Port.\n\nFind Rok'tar to the south - I believe he has set up a command post on one of the shipwrecks - and ensure that the Twilight Shores remain in our control.", completion = "Good timing, {class}. We were just about to unleash a counter-attack.", objectives = "Speak with Rok'tar at the Twilight Shores in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27608] = { id = 27608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "We're about to launch the attack upon the Twilight Gate, but there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nWould you go back in there and kill them?", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27609] = { id = 27609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Heads are Better than None", description = "Now, while we're about to launch the attack upon the Twilight Gate, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nPlease head back in and kill them.", progress = "Is that blood dripping from your pack? I hope that it's not yours.", completion = "<The noble lady grins wickedly.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27610] = { id = 27610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Shore", description = "If the Alliance gains control of this peninsula, they will threaten Dragonmaw Port. Not going to happen.\n\nSouth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand all along the shore!\n\nRush over there and scout the beach head control point. It's marked by that enormous flag. Then return to me.\n\nYou don't have to capture it, unless you're spoiling for a fight with the Alliance.", completion = "Good work, {class}. Now you know the lay of the land.\n\nIf you're ever having difficulty fighting here on the Twilight Shores, remember that capturing and holding the Beach Head will give all Horde forces here a combat advantage!", objectives = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27611] = { id = 27611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood on the Sand", description = "Our objective in the Twilight Highlands is to storm the Bastion of Twilight, but the Alliance have decided to make war.\n\nSo we will give them war!\n\nSlay their marines until the lesson is learned.", completion = "Good, good. Let them reap what they sow!", objectives = "Slay 12 Highbank Marines on the Twilight Shores in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27612] = { id = 27612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory From Within", description = "A few of our men didn't make it through portals which were supposed to open inside this very abbey.  You've already proven your elusiveness and battlehardiness... now I need you to do so again.\n\nThe abbey has two wings: a library, and a hall of arms.  In each wing, you should find a portal.\n\nUse this keystone on these portals.  Doing so should force them open, allowing our remaining shock troopers to take this abbey.", completion = "The abbey will fall shortly.  We can soon move on, deeper into Tyr's Hand.", objectives = "Open the Argent Portals in the Library Wing and the Hall of Arms within the abbey in Tyr's Hand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27613] = { id = 27613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassin", description = "The fate of the Scarlet Crusade is tragic, if somewhat ironic.  At one point, they led the charge of humanity against the undead.  Now, they resemble those corpses that they once hunted.  What caused their descent into undeath isn't certain, but it doesn't make them any less dangerous.\n\nOne of their deadliest was an assassin who went by the name of Rohan.  We have intel that places him atop the bell tower in this very abbey.  Find him and kill him, {name}.  And try not to die on the way.", progress = "Fight well, {name}.", completion = "The death of Rohan eases my spirits a bit.\n\nI once fought beside him, you know.  He was an emissary of the Scarlet Crusade; one of the few that deigned to join us in our battle against Kel'thuzad, so many years ago.  How quickly things change.", objectives = "Kill Rohan the Assassin within the abbey bell tower in Tyr's Hand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27614] = { id = 27614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Salvage", description = "This battle was won before it started.  Right now, we're just shooting for style points.\n\nWithin these barracks, the sniveling Scarlet Crusaders cling to their priceless artifacts, even though some of the objects are too holy for their now-undead hand to touch.  So they keep them in chests, hidden from the world.\n\nYou will find these artifacts, and bring them back to me.  They belong to the Argent Crusade.  They belong in the hands of the righteous.", progress = "I hope you gave them a fight.", completion = "Well done, {name}.  I will deliver these to Tyrosus when we return.", objectives = "Obtain the Crimson Boar, Lihanna's Strand, the Shroud of Uther, and Gavinrad's Sigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27615] = { id = 27615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrathcaster", description = "One of the more vile members of the Scarlet Crusade, Mataus the Wrathcaster, lurks within the barracks' dungeon.  Undeath suits his dark manner.\n\nWere I younger and on the front lines, I'd run him through myself.  As things are, I'm left behind to lead our forces from the rear.  So I leave the pleasure to you.", completion = "You are well on your way to becoming a true champion of the Light, {name}.  Well done.", objectives = "Slay Mataus the Wrathcaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27616] = { id = 27616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Huntsman", description = "We've already lost half a dozen men to a hail of bullets and arrows coming from atop this fortress.  I haven't seen the face of the enemy that's firing, but I don't need to.  I know the name of the man up there.\n\nLeopold.\n\nThat's right, there's only one man up there, picking off my men one-by-one.  And from what I can see, there's only one of you.\n\nSounds like a fair fight to me.", progress = "If it were up to me, I'd throw him off the edge of the tower.", completion = "One less thing to worry about.  Nice work up there.", objectives = "Slay Huntsman Leopold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27617] = { id = 27617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befouled No More", description = "Can you sense it?  The taint is already lifting from this building.\n\nA holy building wants to be holy, and villains like Rohan and the rest of his Scarlet scum only hold it back.\n\nWith the abbey secure, we are a step closer to taking Tyr's Hand.  Report the results of our strike to Angela.  She should be leading the charge on the cathedral from somewhere in the center of town.", completion = "Good, the abbey is ours.  I never doubted Eligor's ability for a moment.", objectives = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27618] = { id = 27618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Upheaval", description = "I'll say we've done enough damage to these barracks to call this a win.  A commander, a huntsman, and a warlock, all slain... not to mention the relics that we've liberated.  Or shall I say... YOU liberated.\n\nThe cathedral still remains, but not for long.  Talk with Archmage Angela Dosantos, in the central courtyard.  The fate of Tyr's Hand's cathedral falls in her able hands.", completion = "It sounds like Korfax really cleaned house over at the barracks.  It's very much like him to show off like that.", objectives = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27619] = { id = 27619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Commander", description = "Scarlet Commander Marjhan is cunning, shrewd, and willing to do anything to win a battle.  Before all these things, however, she is loyal.\n\nI have no doubt you'll find her in the barracks' central chamber, fighting under a crimson banner, until she either wins or dies.\n\nMake sure it's the latter.", completion = "Good, good.  These barracks are as good as fallen.", objectives = "Slay Scarlet Commander Marjhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27620] = { id = 27620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Rats", description = "Well, I'm glad that Eligor and Korfax left some fun for me.  It was a battle unto itself to keep them from rushing headlong into the middle of this cathedral.\n\nThat's YOUR job, after all.\n\nThe cathedral lies ahead of us, the last real bastion of Scarlet power remaining.  Within it, Crusader Lord Valdelmar sits atop Tyr's Hand's crumbling pulpit of lies.\n\nThere will be no escape; there will be no mercy.  The last simpering vestiges of the Scarlet Crusade end here.  Slay him.", completion = "While I can't agree with their methods, I can't argue with their results.  In many ways, the Scarlet were well-intentioned, but their zeal grew too strong, and their hate blinded them to reason.\n\nI only hope that the same doesn't happen to our Brotherhood of Light.", objectives = "Slay Crusader Lord Valdelmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27621] = { id = 27621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard's Patrol", description = "I was on my way to join Firebeard's Patrol when my bird was shot down.\n\nTwilight's Hammer launched surprise attacks all over the Highlands. Sometimes their buildings crawled right out of the earth in the middle of our villages. It was a nightmare!\n\nIn the chaos, Firebeard is one of the few who's kept his head on straight. He's trying to piece together a full gryphon wing from the survivors.\n\nIf you want to bring the Wildhammer into the Alliance, start by helping out Firebeard, to the west.", completion = "Come to join the patrol, lad? Glad to have ya.\n\nI need some bodies helpin' to get our defenses under control here. Help me out and I'll see if I can't find some more prestigious work for ya.", objectives = "Seek out Keegan Firebeard at Firebeard's Patrol in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27622] = { id = 27622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo' Better Shredder", description = "{name}, I've got plans for a better shredder. But my engineers can't wade into a combat zone alone.\n\nGo locate a salvageable shredder in the Twilight Shores, and use it to signal one of my salvage experts to join you. Defend the shredder while we make some \"upgrades.\"\n\nThe Alliance won't know what hit them! At least, not until my marketing campaign kicks in!", completion = "That's right baby! That's right! Cold steel and hot death!\n\nWhat should we name our new creation? The Gnugatron? No - better - the {name}-o-matic. That's got a ring to it.", objectives = "Locate a Salvageable Shredder on the Twilight Shores, and use it to summon a Bilgewater Salvage Expert. Defend the shredder until it is operational again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27623] = { id = 27623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colossal Guardians", description = "The chest containing the scepter appears to be magically sealed and will not budge.\n\nThe plaque above it depicts two giant statues holding star and moon-shaped stones sockets at their center.\n\nThe two statues are pictured guarding pyramids that look like the ones outside.\n\nPerhaps it's worth your while to investigate these.", progress = "You wipe away the sand from the hieroglyphs only for them to become covered in a new layer.  You'd best hurry.", completion = "You place the two gems inside the sockets in the wall.", objectives = "Obtain the Stone of the Moon and the Stone of the Sun from the Colossal Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27624] = { id = 27624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Fall", description = "Aww, that was nothin', really.\n\nThose statues were teetering as it was - just needed a little push is all.\n\nHow about you go and sort through that rubble?\n\nI've got a feeling we're close to getting this all sorted out.", progress = "Find anything interesting, {name}?", completion = "Fine work, {name}.\n\n\n\nIt looks as though our work here is nearly complete.", objectives = "Collect the Orb of the Morning Star, the Orb of the Evening Star, Orb of the North Star and the Orb of the Shooting Star.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27625] = { id = 27625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Quel'Danil", description = "The undead are here! The Forsaken! They've been moving closer and closer, but to launch an all-out attack on us... those horrid abominations!\n\nThe young draenei I was charged with have trained with the Highvale elves in combat. They are not defenseless, but they need help!\n\nPlease, {name}, assist them! Drive back the Forsaken!", completion = "Such aberrations in the face of the light... You are brave to face them, {name}.", objectives = "Slay 16 Deathstalker Invaders at Quel'Danil Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27626] = { id = 27626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highvale Documents", description = "The Highvale have kept detailed records here for years. Deaths, births, seasons... but also vital scouting information and methods of contact with the rest of the Alliance.\n\nThe documents will be scattered in the chaos. If they fall into the hands of the Forsaken, more lives could be at risk! Please, you must retrieve the documents before they are taken by the Horde...", progress = "Are they safe?", completion = "Thank the Light. We will not let the Forsaken have anything that can be turned against us, no matter how small.", objectives = "Collect the Highvale Report, the Highvale Records, and the Highvale Notes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27627] = { id = 27627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Fancy Cockroach", description = "Evidently, the ancient statues were home to various species of scarab.\n\nDetermined to leave this site in the best condition possible, you resolve to ridding the chamber of these pests.", objectives = "Kill 5 Amethyst Scarabs, 5 Sapphire Scarabs, 5 Turquoise Scarabs, and 5 Emerald Scarabs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27628] = { id = 27628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Word to Phaoris", description = "Hurry, {name}.  We must speak to my brother, the king.\n\nHe is bent on averting war with Al'Akir and the Neferset.  He has foolish hopes that there is a diplomatic solution to this problem.\n\nMaybe once he hears what occurred here he will see reason.", completion = "This is just the beginning, {name}.  If Deathwing's minions can bury entire cities, we have little chance of defeating them through conventional means.", objectives = "Speak to King Phaoris at Ramkahen in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27629] = { id = 27629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vizier's Vote", description = "Getting Vizier Tanotep to go against my brother's wishes is going to be extremely difficult.  His very position is based on enforcing the will of Phaoris.\n\nI've had little luck making the case for open war against Neferset.\n\nNevertheless you must speak to him.  Perhaps he will listen to an outsider's perspective.\n\nYou will find the Vizier at the Akhenet Fields on official business.", completion = "What manner of creature are you?  You will leave the king's lands before...\n\nWait!  You are that {name} I've heard so much about.\n\nYou must pardon my lack of hospitality.  We have seen all manner of hostile intruders since the barrier around Uldum failed.", objectives = "Speak to Vizier Tanotep at the Akhenet Fields in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27630] = { id = 27630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Priest's Vote", description = "High Priest Amet's vote is the only one that is completely outside of our control.\n\nHe will vote as his divinations tell him and nothing we do will dissuade him.\n\nI figure that gives us even odds either way.\n\nThe only problem we face is that his clairvoyance has failed him ever since the barriers around Uldum fell.\n\nHe will not cast a vote unless he regains power over his divinations.\n\nTake the stairs at either side of the Vir'naal Dam and Speak to him to see what you can do to help.", completion = "War, you say.\n\nDivinations for war are always difficult.  Some wars must never be fought, even if victory was assured.  Some wars have to be waged even if defeat is certain.", objectives = "Speak to High Priest Amet inside the Vir'naal Dam in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27631] = { id = 27631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Commander's Vote", description = "If we're to pass a resolution for war, the high council's vote needs to be unanimous.\n\nI'm certain High Commander Kamses will give us his vote once he hears about what happened at Orsis.\n\nPlease speak to him in Ramkahen and make sure that's the case.  I must make preparations in case our plan fails.", completion = "No need to fill me in on the events in Orsis, {name}.\n\nI've heard about them already.  And about you.  Any enemy of Al'Akir is a friend of mine.", objectives = "Speak to High Commander Kamses at the Ramkahen Legion Outpost in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27632] = { id = 27632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanotep's Son", description = "I have devoted my life to serving the King.  That service is unrivaled in importance by anything... with one exception: my son.\n\nTahet was captured by Neferset sentries.\n\nThey claim my son was trespassing upon their territory.  Phaoris is attempting to negotiate his release... but I fear for the worst.\n\nIf you were to find Tahet, I would pledge my vote to you.\n\nI do not know where they take the prisoners, but I've seen the guards consult maps to guide them through the thick vegetation.", progress = "This might be the map you're after.", completion = "You've obtained a map of the Vir'Naal river delta.", objectives = "Obtain the Vir'Naal Delta Map from a Neferset Guard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27633] = { id = 27633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood God Hakkar", description = "Hakkar... The mere mention of The Soulflayer's name will send many running. In the Sanctum of the Fallen God the Atal'ai have recovered a significant portion of his skeleton and seek to restore him to life. Already his children have begun to show up in the area.\n\nPlace this egg in that sanctum, and it will force his summoning prematurely. {name}, do not hesitate. Strike once his avatar appears!", completion = "You have successfully stopped Hakkar here, but I fear we are far from done. The Atal'ai transported most of the blood they produced to Zul'Gurub, where the Hakkari work to summon The Blood God there.\n\n{name}, I do not think that this was ever meant to be the place of Hakkar's arrival - it was merely a test to see if the blood was potent enough! Hakkar can only be summoned in Zul'Gurub...and I fear we may be too late to stop the Hakkari with the blood they now have in their possession.", objectives = "Kill the Avatar of Hakkar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27634] = { id = 27634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The God Hakkar", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the Egg of Hakkar.", objectives = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27635] = { id = 27635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decontamination", description = "You've been down here in Gnomeregan for a long time, {name}, and it's amazing that you've survived and kept your wits so long! We need to get you out.\n\nBefore we can send you to the surface to join the rest of the gnomes, you have to go through the decontamination process. Just head into the next room and board the Sanitron 500. It will do the rest! It shouldn't even hurt... much.\n\nWhen you're all done, check in with Technician Braggle and he'll make sure you get some suitable gear.", completion = "There, now you're fit to head off to the surface and start your new life. The High Tinker will be delighted to hear of your arrival.", objectives = "Board the Sanitron 500 to begin the decontamination process.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27636] = { id = 27636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Mathias", description = "The SI:7 are all dead. Time to find Master Mathias Shaw.\n\nGood thing the squad commander told you where he would be.", completion = "Where are the rest of my people?", objectives = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27637] = { id = 27637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Mathias", description = "That's a blow to our efforts. Damn Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Master Shaw.", sourceObjective = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27638] = { id = 27638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Garona", description = "The Kor'kron are all dead. Time to find Garona Halforcen.\n\nGood thing the squad commander told you where she would be.", completion = "Where are the Kor'kron?", objectives = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27639] = { id = 27639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just You and Garona", description = "That's a heavy blow to our efforts. Damn that Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Garona.", sourceObjective = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27640] = { id = 27640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunwalds Don't Die", description = "As I understand it, you're to be looking to bring the Wildhammer clans together with the Alliance for war. Not sure you know what you're gettin' into.\n\nAnyway, if it's battle you're preparin' for, there's definitely one family you want by your side. Head southwest, to the opposite side of the Crucible of Carnage, and there you'll find Clan Dunwald's ruins. They're rightly ravaged, but that's not likely to be stoppin' the Dunwalds. It's just a matter of findin' them.", completion = "If it's Dunwalds you be lookin' for, it's Dunwalds you've found. A couple of'm anyway. I can't find me other brothers for the life of me.", objectives = "Look for Dunwald family survivors in the Dunwald Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27641] = { id = 27641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While Meeting The Family", description = "Hey there, <lad/lass>. I'm sure Keely's got you worrying about our brothers, but they can take care of themselves. They'll find their way back here one way or another.\n\nMaybe you can do me a favor while you're out meeting the family... Dunwald territory is still infested with Twilight's Hammer and their servants. I'd appreciate it if you could remind them that they're not welcome.", completion = "Now that's what I'm talkin' about lad. My kinda {race}.", objectives = "Kill 20 Twilight's Hammer in Dunwald territory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27642] = { id = 27642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sifting Through The Wreckage", description = "The Twilight's Hammer were damn thorough when they sacked our town.  Me and me brothers may well be the only ones that held'm back. I gotta be sure though.\n\nAs you're siftin' through the ruins, keep an eye out for the bodies of me kinsmen. I wanna know if dere were any survivors... or if it seems like some might have gotten away.", completion = "That many dead, eh? Not seemin' likely that anyone outside of me brothers fought through it then. I guess I already expected as much.\n\nThanks for takin' the time to look for me.", objectives = "Search for the bodies of 12 Dunwald Victims.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27643] = { id = 27643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnelly Dunwald", description = "So you be lookin' to find us, and I be lookin' to find me brothers. It sounds to me like we got some common ground in there abouts.\n\nDonnelly's our eldest, and while his size shows it, his wits might not. He's usually up in the northern ruins - in the hovel. Do ya think you might go lookin' for him for me? It'd be a right comfort if I knew he were safe.", completion = "Hi friend! I don't think I know you... I'm Donnelly Dunwald.\n\nWhat's your name? I don't think I know you... Do I know you?", objectives = "Find Donnelly Dunwald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27644] = { id = 27644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eoin Dunwald", description = "Eoin's one of the twins. He's got a penchant for the drink. You'll likely be findin' him over by the old well - the ale stores were in a building there.\n\nMind making him to pay his worrying sister a visit? Shouldn't take much convincin' if you can get to the ale first.", completion = "Of all the buildings in all the towns to collapse, why'd it have to be this one?!", objectives = "Find Eoin Dunwald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27645] = { id = 27645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cayden Dunwald", description = "Cayden's the other twin. He's got a thirst too, but not for ale. I'm sure he's been havin' a grand time of it since the Twilight came to our doorstep. Gettin' some of that aggression out of his system mayhaps.\n\nI'm thinkin' the best place to go lookin for him is at market row, by the old smithy. He used ta hang out there anyway, but since that place is swarmin' with the most Twilight, he's probably got all the more reason to be callin' it home now.\n\nBring'm back for me. In one piece would be nice.", completion = "Well look at ya, all geared and fancy. Keely send you to keep an eye on old Cayden, eh? Won't be needin' it. I got these louts handled.\n\nHahah! They chose the wrong dwarf to be ambushin' today! Ahahahahah!", objectives = "Find Cayden Dunwald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27646] = { id = 27646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Beak", description = "I lost me gryphon. Beak! Where are you Beak?!\n\nWanna help me find him? I know he's in da hovel. He hasta be.\n\nBeak?! Wheres are ya?\n\nI hope he's okay.", progress = "Did you find'm?! Please?", completion = "You found'm! You found Beak! I like you, new friend!\n\nI'm gonna go show Keely. Keely like Beak too.", objectives = "Help Donnelly find Beak in Dunwald Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27647] = { id = 27647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anything But Water", description = "Look, buddy. Either you're here to help me find some drink, or you're in the way.\n\nWhy don't ya go down to the old storehouse and look downstairs. I had a mighty suspicion that ol' bookkeeper up in there was sneaking sips between pages. I bet he has a keg in his basement!\n\nIf ya find anything, come straight back to me! No dallyin'... this is urgent!", progress = "You stink of sober! Find me some drink!", completion = "Donnelly's belly! That's more like it. Good to not be dyin' of the thirst again.\n\nHere, have some. Good ol' Eoin's never so impolite as ta not share!", objectives = "Check the cellar Eoin Dunwald mentioned for a keg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27648] = { id = 27648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Into The Fire", description = "Fine, fine. You want a piece of the action? You can join in.\n\nLet me know when you're ready ta go.", progress = "They keep comin an' I'll keep swinging!", completion = "A thing of beauty, isn't it? An' they keep comin' back for more. Love it!\n\nI'll go find Keely and settle her nerves in a bit. Just one more go through the row.", objectives = "Accompany Cayden Dunwald through the somewhat obvious ambush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27649] = { id = 27649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steady Supply", description = "Hey bud. Seeing as how you're so friendly and great and all, think you might do a dwarf a favor?\n\nThese are Dunwald ruins... there's SURE to be more stock in some of these buildings. If you come upon more ale, bring it my way, will ya? A good dwarf can never have enough!\n\nI'm thinkin' I'll find my way back to Keely, so ya might have to hunt me down, but I'll try'n make it worth it to ya.", progress = "Where's me booze?", completion = "Woooooh! That's exactly what my belly needs!\n\nYou get me all the nice things.", objectives = "Collect 6 Barrels of Wildhammer Ale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27650] = { id = 27650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Again", description = "Ya should find Keely. She'll be eager for word.", completion = "Thank you for bandin' my brothers back together. I know they're tough, but they're even tougher when they're side by side, and there's a lot of Twilight out there.\n\nYou're good to put a gal's heart at ease.", objectives = "Speak to Keely Dunwald at the Dunwald Holdout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27651] = { id = 27651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing It Like a Dunwald", description = "They already left to hunt down the ettin that lead the attack on Dunwald. I asked them to at least give ya a chance to catch up, but I'm not sure waitin's in their blood.\n\nThey made off towards the town square, in the center of the ruins. You should go join'm before ya miss out on all the fun.", completion = "Thanks for your help. You've got a warrior's spirit in ya - you coulda fooled me for a Wildhammer if it weren't for your... well.. you know.\n\nI know Firebeard sent you to unite us. My love for that dwarf runs shallow, but you know now we've got plenty of reasons to make enemies of Twilight. If you see him, tell him that when the battle starts, the Dunwald family will be there.", objectives = "Speak to Flynn Dunwald and aid the Dunwald brothers in killing Darunga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27652] = { id = 27652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Assassins", description = "Even I get hunted. I suppose that's what I get for hiding amongst the sheep.\n\n<Mathias studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice bunch of guys. Dead now. They're made from the souls of the most skilled killers.\n\nWant to do me a favor? Hunt them down. Bring back their soul pendants.", progress = "How many pendants do you have?", completion = "I'm not sure what I'm going to do with all of these. I'll probably fence them and donate the proceeds to the Stormwind orphanage.\n\nNow to find someone sick enough to buy such a thing. It'll probably be a goblin. Or, a gnome warlock.", objectives = "Collect 5 Dark Assassin Pendants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27653] = { id = 27653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Assassins", description = "Even I get hunted, {class}. But that's part of the fun of hiding amongst the sheep.\n\n<Garona studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice for a group of dead guys. They're made from the souls of only the most skilled killers.\n\nDo me a favor? Hunt them down.\n\nThey wear their souls in pendants about their necks. Bring them back to me. Souls optional.", progress = "How many pendants do you have?", completion = "What do you think I should do with all of these? Maybe I'll melt them down and have the metal imbued into a new dagger that I can thrust into Cho'gall's chest.\n\nThink there's time for that?", objectives = "Collect 5 Dark Assassin Pendants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27654] = { id = 27654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Hammer Down", description = "No foray into the field would be complete without a good old-fashioned take-the-bad-guys-out kind of mission.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, I'm sure you'll have plenty of targets.\n\nHow you choose to kill them is up to you.", completion = "None of us are too good to get our hands a little dirty. Or bloody, in this case.", objectives = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27655] = { id = 27655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring the Hammer Down", description = "There's nothing worse than a self-hating Twilight's Hammer cultist. Nothing! These idiots actually want to bring about the end of the world.\n\nThat marks them for extinction in my book.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, you should have no shortage of targets.\n\nI could care less how you choose to kill them.", completion = "Feels good to get a little blood on your hands, doesn't it? Especially when that blood belongs to such self-deluded fools.", objectives = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27656] = { id = 27656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Croc-Out", description = "The Stagalbog east of town is swarming with crocolisks. Swarming, you hear me? I've sold every bit of crocolisk you could imagine.\n\nCrocolisk hides, teeth, tails, tongues, eyes, you name it. My point is, they ain't sellin' anymore. There's too many crocs! We're over-supplied and under-demanded.\n\nSo since they're of no use to me, and they occasionally eat my guests, I need you to just kill the suckers. Do me the favor, eh? I'll be here negotiatin' things with your people.", completion = "All taken care of? Good to hear. Takes a load off my mind.\n\nNow I can focus on proper business for the fine folk of Marshtide and Stonard, weary from the war... and all that junk.", objectives = "Slay 8 Sawtooth Crocolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27657] = { id = 27657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Mathias spits.>\n\nWe need help. There's an Earthen Ring woman, Earthcaller Yevaa, southwest at the Elementium mine.\n\nShe and her goblin initiate need help with the shutting down the elemental portals hereabouts. I'm thinking that in exchange, she can help us with our problem.", completion = "{name}! I'm glad you're here.\n\nOf course, I'm more than happy to lend you whatever assistance that I can.", objectives = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27658] = { id = 27658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Garona spits.>\n\nI hate to say it, but we need help. There's an Earthen Ring woman, a draenei named Earthcaller Yevaa.  She and her pet goblin are southwest at the Elementium mine.\n\nThey need help with shutting down the elemental portals around here. In exchange, she can help us with our problem.", completion = "{name}! I'm glad you're here.\n\nOf course, I'm more than willing to help you in any way that I can.", objectives = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27659] = { id = 27659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal Overload", description = "I used to be the caretaker of the Earthen Ring's portals here. But while we were away helping to save Deepholm, the Twilight's Hammer moved in and corrupted the area.\n\nThey're using powerful ascendants to guard our portals. That's where they've made a critical error.\n\nI want you to go to the portals and use the controllers to overload them. This will unleash all of the portal's energy, debilitating the ascendant. Slay it.", completion = "The last portal is deep within the mine here, but we'll deal with that in a bit.", objectives = "Slay Debilitated Apexar, Debilitated Aetheron, and Debilitated Edemantus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27660] = { id = 27660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Loch", description = "I have no knowledge of any artifact that Cho'gall is crafting, but I think I know one that can help.\n\nCountess Verrall is the ancient spirit of Loch Verrall to the north. She has no love for the Twilight's Hammer, who have polluted her waters.\n\nSeek her for the wisdom that you seek.", completion = "I know why you are here, {name}. Your reasons sing within your fluids.\n\nI know about the dead dwarf forgesmith polluting my lake. If you want to find out what his corpse remembers, you must earn it.", objectives = "Speak with Countess Verrall at Loch Verrall in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27661] = { id = 27661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire the Cannon", description = "My arch-nemesis, Lord Cannon, has foolishly decided to throw his allegiance to the Twilight's Hammer.\n\nIn the past, we've coexisted with a shaky truce, but his change of heart leaves me little choice but to put an end to him. Or, I should say, if you want the information that you seek from the dead dwarf, you're going to kill Lord Cannon for me.\n\nSeek him at Cannon's Inferno to the southeast.", completion = "I am pleased. Lord Cannon was always an unworthy adversary.\n\nVery well, {race}, I will help you gain the information which you seek.", objectives = "Slay Lord Cannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27662] = { id = 27662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbinding", description = "Look, if there's one thing I know, it's elementals. I've been able to really gain an appreciation for how they feel. Let me tell you, they don't appreciate being enslaved one bit!\n\nSo, what I'm saying here is that if you were to free the enslaved elementals, I'm sure that not only would they show their gratitude, they'd also likely turn on their masters.\n\nSounds like a win-win to me, {name}.", completion = "What'd I tell you? Elementals aren't so bad after all, eh?", objectives = "Free 10 Enslaved elementals by slaying them at the Twilight Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27663] = { id = 27663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tastes Like Strider", description = "You there! Yes, you! You want a good word put in with the Trade Baron? Give me a hand!\n\nI heard you're the one that got all those makrura tails. They're wonderful, but not enough for proper swamp food. I need drumsticks for my gumbo!\n\nThere's plenty of swampstriders just outside town in the Sorrowmurk. I want the biggest drumsticks you can find!", progress = "Have you got those drumsticks?", completion = "Ah, good, good! Just what I needed.", objectives = "Collect 9 Jumbo Swampstrider Drumsticks from Swampstriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27664] = { id = 27664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Volcanic Deck", description = "Now that you have gathered all of the Ember cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Volcanic deck!   Congratulations!", completion = "So you have put together a deck of Embers.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Volcanic Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27665] = { id = 27665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Hurricane Deck", description = "Now that you have gathered all of the Wind cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Hurricane deck!   Congratulations!", completion = "So you have put together a deck of Hurricanes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Hurricane Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27666] = { id = 27666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Tsunami Deck", description = "Now that you have gathered all of the Wave cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Tsunami deck!   Congratulations!", completion = "So you have put together a Tsunami deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Tsunami Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27667] = { id = 27667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Earthquake Deck", description = "Now that you have gathered all of the Stone cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete an Earthquake deck!   Congratulations!", completion = "So you have put together a deck of Earthquakes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Earthquake Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27668] = { id = 27668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay Attention!", description = "Listen, {race}. It's not that I don't appreciate the rescue and all, but this is a dire situation.\n\nYou have to pay better attention out there!\n\nI was watching, and you passed right over a busted alliance crate.\n\nThere's bound to be something in there that could help me and my boys.\n\nHow about you get out there and take a look-see, hrm?", completion = "Sure enough...\n\nThis looks to be something that Nazgrim will take quite an interest in.", objectives = "Nazgrim wants you to see what lies in the broken Alliance crate north of The Immortal Coil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27669] = { id = 27669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the Honors", description = "It looks like all that's left to do is to place the orbs on the pedestals at each corner of this mechanism.\n\nWe appear to have stumbled upon what may be the most important find in modern history.\n\n<Harrison looks at you for a moment, then hands you the orbs.>\n\nWell, go ahead, {name}.\n\nWe'd have never made this discovery without you.", completion = "Well, now. Would ya look at that!\n\nAs amazing as this is, I am confident that there's more to our discovery than meets the eye...\n\nMuch more.", objectives = "Use the Orbs of the Stars near the mechanism in the Chamber of the Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27670] = { id = 27670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinned Down", description = "My name is Nevin Twistwrench and I'm the commander of the Survivor Assistance Facilitation Expedition, or S.A.F.E.\n\nI don't know how you managed to survive the radiation down here, {name}, but most of the others haven't fared so well. My team is rounding up the survivors, but the radiation-addled leper gnomes are too numerous for us to hold back much longer. They've lost their minds!\n\nIf you're still strong enough to wield a weapon or cast a spell, would you help us clear out some of these leper gnomes?", progress = "Help my men get the way cleared out so we can help the other survivors get out of here!", completion = "Well done, {name}. My men can take it from here. Let's focus on getting the other survivors out now.", objectives = "Kill 6 Crazed Leper Gnomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27671] = { id = 27671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See to the Survivors", description = "If we don't do something quick, neither Nevin nor the survivors will make it out of here alive. I'm going to give you my squad's emergency teleport beacon. We still have enough strength and ammunition to fight our way out of here, but those survivors are in no condition to make a run for it.\n\nUse the beacon on survivors to arrange for them to be teleported out of here to the safe area my men have set up. Once you've done that, report back to me and we'll make arrangements to get you out of here.", progress = "Nevin's team found a lot of survivors this time, but he's cutting it awful close.", completion = "I know Nevin will be pleased with all the survivors you managed to help. I still can't believe you managed to stay so strong down here in the radiation. You've seen the shape the other survivors are in.\n\nLet's get you to the loading room for decontamination.", objectives = "Use the Teleport Beacon to teleport 6 Survivors to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27672] = { id = 27672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a door which leads to the legendary Chamber of Khaz'mul. Who knows what secrets could be hidden inside!\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to unlock the secrets of Uldaman!", completion = "Don't worry about the chamber, my boys will check it out! You have more important things to do!", objectives = "Defeat Ironaya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27673] = { id = 27673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's What's Inside That Counts", description = "The Makers built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI fear that one of the Old Gods is responsible for this, and you're going to help me see if that's the case! Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", progress = "Where are the cores, lad? By Muradin's Beard, where are the bloody cores?\n\n<Kand takes a deep breath.>\n\nSorry about that. Have you been able to obtain the cores?", completion = "This is incredible, {name}. The power coursing through each core...the contrasting powers so close together!\n\nI'll take this to the proper dwarves right away. These cores are extremely important!", objectives = "Obtain the Obsidian Power Core and the Titan Power Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27674] = { id = 27674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Surface", description = "Nevin has just sent word that he and his men are making their way to the surface. He'll be waiting for you in the building that S.A.F.E. has established as its headquarters.\n\nSee Torben Zapblast over there? Talk to him when you're ready to head to the surface and he'll arrange to have you transported up there. It's been a pleasure meeting you, {name}, and I'm honored to have played a small role in helping you escape from Gnomeregan to start your life on the surface.", progress = "It's good to see you again, {name}.", completion = "It's good to see you again, {name}. Without your help, we wouldn't have been able to get so many survivors out of Gnomeregan this time. Everyone is going to be thrilled to meet you and hear your story.", objectives = "Speak to Torben Zapblast to get teleported to the surface and report to Nevin Twistwrench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27675] = { id = 27675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Documents", description = "Find a resident in Stormwind City to accept your forged documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>", objectives = "Find a resident of Stormwind City to accept your Forged Documents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27676] = { id = 27676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Explorers' League is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", completion = "Fantastic! Great work! We'll know all that Dig Three has to tell us in no time at all!", objectives = "Kill Galgann Firehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27677] = { id = 27677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. The secrets on these discs could change everything about how we view our world. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe problem is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for the Explorers' League!", completion = "Well done, lad! Now go to the discs and learn all you can!", objectives = "Defeat Archaedas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27678] = { id = 27678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Platinum Discs", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", objectives = "Speak with stone watcher and learn what ancient lore it keeps. Then, tell Lead Prospector Durdin what you found out!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27679] = { id = 27679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a locked door which I believe leads to the legendary Chamber of Khaz'mul. We do not yet know what artifacts wait inside it.\n\n\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to progress any further into this place.", completion = "Reliquary agents are en route to investigate the chamber. You have more important matters to attend to.", objectives = "Defeat Ironaya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27680] = { id = 27680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. These platinum discs could grant our order unbelievable power. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe only problem in obtaining them is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for The Reliquary.", completion = "You are a most reliable agent, {name}. Proceed to the discs and learn all you can. Report back to me immediately after.", objectives = "Defeat Archaedas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27681] = { id = 27681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Reliquary is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", completion = "Well done. Dig Three and any secrets beyond that door will soon be ours and ours alone.", objectives = "Kill Galgann Firehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27682] = { id = 27682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Minerals", description = "The Titans built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI suspect that one of the Old Gods is responsible for this, and you're going to help me see if that is indeed true. Topple both of the guardians and bring me their power cores. They'll tell us all we need to know.", progress = "Do you have the cores with you, or are you just here to chat? Perhaps we should stop this whole charade and enjoy some snacks and fine wine instead?", completion = "Both of these cores are still far more potent than most of the cores we use  to power our own protectors, and these are ancient devices!\n\nThank you, these will prove extremely valuable to our society.", objectives = "Obtain the Obsidian Power Core and the Titan Power Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27683] = { id = 27683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Woods", description = "I saw the strangest commotion coming through town the other day.  A horse-drawn cart, loaded with crates and chests, a worgen woman at the reins, a blood elf by her side, and a dwarven paladin running behind, yelling some of the most creative obscenities I've heard in quite some time.\n\nThey looked like they were headed to Eastern Plaguelands, though I'd imagine they can't be far past the Thondroril River by now.  I wonder what they were up to?", completion = "Yes?", objectives = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27684] = { id = 27684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visitors", description = "My sources at the Menders' Stead have informed me that we will be having some visitors soon.  A group of paladins - led by a worgen tradeswoman, of all things - will be arriving here shortly.  I look forward to meeting them.  Particularly one of them.\n\nWould you mind stopping in and checking in on them?  I can't say for sure, but by the time you get there, they should just be crossing the Thondroril River, far to the west.", completion = "Yes?", objectives = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27685] = { id = 27685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Deed Left Undone", description = "G'day, <laddie/lassie>.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nSo... in our rush ta git over here, we left a little unfinished business off to the east a ways.\n\nA little lady was near death herself. We had no choice but ta leave her by a little air vent when we came here to yer rescue.\n\nHow bout yeh git over and help her while there's still time?", completion = "Oh, finally...\n\nI don't know how much longer I can last!", objectives = "Speak to Adarrah in the Kelp'thar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27686] = { id = 27686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Documents", description = "Find a resident in Orgimmar to accept your forged documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>", objectives = "Find a resident of Orgimmar to accept your Forged Documents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27687] = { id = 27687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opened Can of Whoop Gnash", description = "What an accomplishment, felling a  mighty sea giant!\n\nThe new residents of Smuggler's Hole will feel considerably safer knowing this monster is no longer loitering outside their haven.", progress = "You took down that Sea Giant, {class}?", completion = "It's not much, but it's all I've got down here.\n\nYou're more than welcome to it, {class}.", objectives = "Bring Gnash's Head to Samir in Smuggler's Hole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27688] = { id = 27688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distract Them for Me", description = "There are three candidates for Ascendancy that we need to eliminate: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI'd like for you to serve as my distraction. When the time is right, I'll step in and finish them off from behind.\n\nWhatever you do, {name}, do not underestimate them. Each got to where they are by being ruthless and very good at what they do.", completion = "That takes care of most of their leaders outside of the Bastion of Twilight.\n\nWe work well together, {name}.", objectives = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27689] = { id = 27689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distract Them for Me", description = "There are three candidates for Ascendancy that need killing: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI want you to serve as a distraction. When the time is right, I'll step in to finish them off from behind.\n\nJust make sure that whatever you do, you don't underestimate them, {name}. Each of those lunatics got to where they are by being ruthless and very good at what they do.", completion = "That takes care of most of their leaders outside of the Bastion. Not bad work, {name}. Not bad at all.", objectives = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27690] = { id = 27690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, the Drake-Tamer", description = "{name}, the stronghold at Bloodgulch is the heart of the Dragonmaw empire in the Highlands. It is just up the river. Narkrall Rakeclaw is using his considerable power to amass a wing of drake-riders there.\n\nFor the Dragonmaw to succeed, Bloodgulch must succeed. Go to Narkrall and make sure it is so.", completion = "<Narkrall sizes you up.>\n\nAnother mewling Horde whelp? Zaela saps our strength by diluting our forces with the weak. Very well, {class}. Prove yourself to me, and show me what your Horde is made of.", objectives = "Report to Narkrall Rakeclaw at Bloodgulch in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27691] = { id = 27691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshfin Madness", description = "I'm afraid the rest of the Steamwheedle here are gone. All the young ones at the camp to the east were lost when the murlocs came.\n\nYes, there's always been murlocs on these shores... but not in these numbers. They came in droves from the sea at night, howling and frothing, swarming up onto the land to attack!\n\nWe can't have them still running around, now can we? Would you put an old goblin at ease and go beat some of them back into the water?", progress = "I've still got a few tricks up my sleeve, but I'm not going to tussle with murlocs if I don't have to.", completion = "You have to wonder just what's out there. This is the coast of the Forbidding Sea, with nothing beyond its reaches... but all these fishy folk just stomped right out of it.\n\nWhat's more, I saw where they've been going...", objectives = "Slay 12 Marshfin Murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27692] = { id = 27692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Princess Theradras", description = "Do not be alarmed, young {race}. I am Zaetar, son of Cenarius, and I come to you for your assistance.\n\nLong ago, I made the mistake of mating with Princess Theradras, a powerful earth elemental aligned with the Old Gods. Our children, the centuar Kahns, turned on me upon birth and slew me mercilessly. Now, Theradras' taint runs deep and threatens far more than just Maraudon.\n\nCome slay her and free my spirit so that we may restore Desolace to a place of verdant life and promise, as Cenarius would want.", completion = "Thank you, {name}. As you can see, my mere presence here has resulted in a bloom of glorious life despite my mate's presence. Names aside, perhaps one day you will again venture into Desolace and find it a verdant oasis free of any traces of the Old Gods.", objectives = "Kill Princess Theradras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27693] = { id = 27693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", objectives = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27694] = { id = 27694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool of Tears", description = "The trolls that lurk within this temple have done grievous harm to my kind, {name}. We were sent here to guard this place, and were instead used to unleash the terrible powers within.\n\nI must beg you for the help only a mortal can give. You can be my hand within the temple; should I enter by myself, I risk being turned against my brothers as well.\n\nWe shall make a pact. If you wish to help, first gather Atal'ai artifacts from the waters around the temple, and return them to me.", progress = "Your gathering of these artifacts will be a sign of faith. Once rendered, I will perform the ritual.", completion = "The essence of the green dragonflight wafts from these artifacts; the vestiges of my corrupted kin. In purifying them, I form a bond between us.\n\nStep forward, {name}, and receive the Oathstone of Ysera's Dragonflight.", objectives = "Collect 5 Atal'ai Artifacts from the Pool of Tears surrounding the Temple of Atal'Hakkar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27695] = { id = 27695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elementium Axe", description = "The Twilight cowards have captured and killed too many red dragons, but one yet lives. Do you remember Lirastrasza? She's shackled nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut through her chains.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", progress = "Do you have the axe? They're going to kill Lirastrasza soon.", completion = "That thing looks sharp. Sharp enough to the do deed, at least.\n\nBut if I'm a judge of weaponry, that's not what Cho'gall's after.", objectives = "Obtain the Elementium Axe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27696] = { id = 27696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elementium Axe", description = "The Twilight cowards have captured and killed many red dragons, but one's still breathing. Do you remember Lirastrasza? She's chained nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut her free.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", progress = "Do you have the axe?", completion = "That's a very sharp axe. It'll do the job, but if I'm any judge of weaponry, that's not what Cho'gall's after.", objectives = "Obtain the Elementium Axe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27697] = { id = 27697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption in Maraudon", description = "{name}, I require your assistance immediately! I am Zaetar, son of Cenarius, and I am trapped here after an unfortunate series of events! Before saving me is an option, you must help me clean out the corruption that runs so rampant through Maraudon.\n\nLord Vyletongue is the satyr ruler of the purple crystal caverns. He is an insidious agent of the Burning Legion and his continued presence can only lead to chaos and death. He can live no longer!", completion = "Excellent work, {name}! Eliminating Vyletongue's presence is a key step to freeing me and, ultimately, saving these lands from corruption. Take this as a token of my thanks and an incentive to continue your work here.", objectives = "Kill Lord Vyletongue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27698] = { id = 27698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Theradras", description = "Princess Theradras, my former mate, has used her enormous power to corrupt the very nature of Maraudon. Even now her creations run rampant here, and I fear that they may soon escape into the open world to sow the seeds of death and destruction.\n\n{name}, venture forth and kill Noxxion and Razorlash. They are two of her most powerful minions and their deaths would cause the callous Princess much deserved grief and suffering of her own. Then, perhaps, you can help free my spirit from her grasp.", completion = "Without her powerful servants, Princess Theradras is significantly more vulnerable. Find her lair, {name}...it is time to strike.", objectives = "Kill Noxxion and Razorlash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27699] = { id = 27699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Weak", description = "That's one tough shark!\n\nYou determine that it's in everyone's best interest to try and distract Budd and hope his attention never returns to Gnaws and this Skeletal Reef.\n\nPerhaps the teeth of the beast will prove captivating enough...", progress = "Whatcha got there, pal?", completion = "What?!\n\nGnaws ain't dead?!\n\nThis kinda takes the quick outta my get rich quick scheme...\n\nThem giant shark teeth are nice and all, but we can't stop 'til that shiney is ours!", objectives = "Collect 5 of Gnaws' teeth from the Skeletal Reef.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27700] = { id = 27700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her.\n\nI need you to take the Elementium Axe and free her from her bonds.", progress = "Use the axe to break Lirastrasza's chains.", completion = "Isn't she a beauty?\n\nLet's see what she does now that she's free.", objectives = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27701] = { id = 27701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her, {class}.\n\nYou need to take the Elementium Axe and free her from her bonds before they do.", completion = "Isn't she beautiful? So graceful.\n\nI hope she gets her fill of revenge and then some.", objectives = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27702] = { id = 27702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are drakes that she's downing that need finishing off, {name}. Wouldn't want the Twilight's healers to get them back up into the air.\n\nTime for a little Coup de Grace.", completion = "Our efforts to improve relations with the red dragons has really paid off, {name}.", objectives = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27703] = { id = 27703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are still drakes that she's downing that need finishing off, {name}. We don't want the stinking Twilight healers to get them back up into the air.\n\nTime for a little Coup de Grace.", progress = "That's all? I think that you can finish off a few more.", completion = "Good thing that you and Warlord Krogg made friends with the red dragons.", objectives = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27704] = { id = 27704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legends of the Sunken Temple", description = "I will need you to enter the temple first, {name}. I can join you once a path is secure, but I dare not enter blindly. Turned against my kind, I would be a vicious enemy.\n\nYou can start by descending the stairs behind me. Then, swim through the flooded depths of the Broken Hall. Once there, follow the passageway to the right to find the Hall of Masks.\n\nBeware of any temple guards. Once you have found the Hall of Masks, I will contact you through the Oathstone.", progress = "You must not falter, {name}. Your actions will pave the way for me to enter the temple myself.", completion = "This is it!\n\nThese are the bones of my kin...", objectives = "Journey through the antechambers of the temple to the Hall of Masks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27705] = { id = 27705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step One: The Priestess", description = "My brethren are being butchered here. It's as I thought.\n\nI must ask your help further before I enter, {name}. In the passageway outside this room, the hallway proceeds left and right. To the right, it goes down to the Chamber of Blood. Here the Atal'ai perform their dark rituals.\n\nThey have expected and prepared for my kind for years, but not for you. Enter the Chamber of Blood and slay the Priestess Udum'bra. She is one of three foul presences here that must be vanquished before I may enter.", progress = "You must not falter, {name}. Your actions will pave the way for me to enter the temple myself.", completion = "Good riddance. Another source of corruption in this world put to rest.\n\nI thank you for your bravery, {name}.", objectives = "Slay Priestess Udum'bra in the Chamber of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27706] = { id = 27706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scepter of Orsis", description = "The chest below unlocks with a loud click as you insert the two stones into the plaque.\n\nObtain the scepter and bring it back to General Ammantep.", progress = "You're back, {name}!", completion = "So... this is what Al'Akir wanted all along.", objectives = "Obtain the Scepter of Orsis from the Sacred Receptacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27707] = { id = 27707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neferset Prison", description = "Hieroglyphs depicting a chained Tol'vir mark the southeastern corner of the map.\n\nPerhaps Tahet was brought there when he was imprisoned.", objectives = "Go to the Neferset Prison Camp and find the whereabouts of Tahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27708] = { id = 27708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warden's Time", description = "<Erunak's image penetrates your mind.>\n\nYou have done well, {name}, but more remains to be done.\n\nBefore moving on from this place, let us be sure that we leave it in disarray.\n\nFind the one who leads these naga and repay him for his misdeeds.", completion = "It is good that this operation has been undone.\n\nSoon, I must move on...", objectives = "Erunak Stonespeaker wants you to slay Warden Azjakir at The Clutch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27709] = { id = 27709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", objectives = "Complete the Sentinel's Game by connecting the two red statues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27711] = { id = 27711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Elementium Depths", description = "The Earthcaller's initiate, Goldmine, has need of you.\n\nI think that they're ready for you to help them with whatever's down in that mine.", completion = "{name}, glad you're back! Have I got something fun for us to do!", objectives = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27712] = { id = 27712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Elementium Depths", description = "The Earthcaller has a goblin initiate? Goldmine is his name? He has need of you.\n\nI think that they're ready for you to do their dirty work with whatever's down in that mine.", completion = "{name}, glad you're back! Have I got something fun for us to do!", objectives = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27713] = { id = 27713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came", description = "Deathwing made quite a mess when he passed through these parts.  If it weren't for me, he'd probably still be here, layin' waste to all the good people of the Badlands.\n\nWhat, you don't believe me?  Fine, let me tell you the whole story.", progress = "Are you going to listen or not?", completion = "Some story, huh?  Now you know why Deathwing hasn't come back here since.", objectives = "Listen to Theldurin's tale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27714] = { id = 27714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came: The Real Story", description = "Not only was Theldurin's story wrong, it was boring, unimaginitive, and slow.\n\nI'll tell you how things really happened on that day.", progress = "I'm not done with my story yet.  Sit back down.", completion = "The end!  No moral.", objectives = "Listen to Lucien Tosselwrench's version of the story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27715] = { id = 27715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day that Deathwing Came: What Really Happened", description = "These two have no idea how to tell a story.  Theldurin's story was too short, and Lucien's tale was a little too tall, if you catch my drift.\n\nAlso, neither of their stories had action and fans admiring my awesomeness in them.\n\nSit back, {name}.  I'll tell you what really happened that day.", progress = "I seem to have lost my place... let's see... where was I...", completion = "I can't believe those guys would interrupt me like that.  My story was going so well, too...\n\nAnyhow, thanks for sticking around so long.  It's nice to have someone new to share tall tales with.  I'm sure Lucien and Theldurin feel the same way.\n\nYou have any you'd like to share with us?", objectives = "Listen to Martek the Exiled's version of the story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27716] = { id = 27716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Levia Dreamwaker, back with the Nespirah survivors, was looking for something exactly like this.>", progress = "Hah! Did you see the admiral giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! It will take me a while to translate, but this is precisely the kind of find I was hoping for.\n\nThere's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, {name}. Here... perhaps I have something that may be of use to you.", objectives = "Bring the Ancient Elven Etching to Levia Dreamwalker. You should find her with the Alliance Nespirah Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27717] = { id = 27717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Elendri Goldenbrow, back with the Nespirah survivors, was looking for something exactly like this.>", progress = "Hah! Did you see the captain giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! I can't have expected much more with the tools I gave you.\n\nI should be able to fill in the blanks and get this all written out shortly. There's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, {name}. You're not bad.", objectives = "Bring the Ancient Elven Etching to Elendri Goldenbrow. You should find her with the Horde Nespirah Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27718] = { id = 27718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Vashj'ir!", description = "All able-bodied members of the Horde are hereby ordered to report to Commander Thorak at Bladefist Bay in Durotar.\n\nNow, more than ever, your help is needed in battling our most hated enemy, the Alliance!\n\nTo reach Bladefist Bay you must travel south through the main gates of Orgrimmar and enter Durotar. From there, follow the path east to the coast. Thorak will be standing at his post near the docks.\n\nOnward, <brother/sister>! Destiny calls!", completion = "Lok'tar, brother! You have arrived just in time.", objectives = "Report to Commander Thorak at Bladefist Bay in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27719] = { id = 27719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen, take your information and be gone from my demesne.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?", objectives = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27720] = { id = 27720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!", objectives = "Ride the mine cart with Initiate Goldmine to the end of the line.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27721] = { id = 27721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Mount Hyjal!", description = "All able-bodied members of the Horde are hereby ordered to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Blackhoof to gain entry into Moonglade. Blackhoof is located at the tauren district in the Valley of Wisdom in Orgrimmar.\n\nOnward, <brother/sister>! Destiny calls!", completion = "We knew the Horde would send help and not a moment too soon!", objectives = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27722] = { id = 27722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Deepholm!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Krogar at the Western Earthshrine in Orgrimmar.\n\nThe Earthen Ring, lead by our former Warchief, Thrall, requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world!\n\nThe Western Earthshrine can be found just north of the Valley of Wisdom.\n\nOnward, <brother/sister>! Destiny calls!", completion = "Our world is in danger, {name}! We need the help of great heroes, like you, to save it!", objectives = "Speak with Farseer Krogar at the Western Earthshrine in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27724] = { id = 27724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Vashj'ir!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Recruiter Burns in Stormwind Harbor.\n\nRecent attacks by the Horde on our trade ships must be met with swift and just force!\n\nStormwind Harbor can be found in the northwest region of Stormwind City.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", completion = "All of our war ships are off fighting the Horde. You'll have to take the mercenary ship.", objectives = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27725] = { id = 27725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quel'Danil Lodge", description = "I may appear far from home to you, {class}, but quite a few of my people were led here by Ambassador Rualeth. We have settled with the high elves of the Quel'Danil Lodge, to the northwest, to train in the ways of the Light and enjoy the peaceful beauty of this land.\n\nSuch peace may be short lived. We have seen the Horde moving further west from here. Could you travel to Quel'Danil and give warning to Anchorite Traska? Her cabin is just north of the main lodge.", completion = "Yoro sends warning of the Horde? The Highvale have been cautious of an attack for some time now. In fact, we have been--\n\n<Screams and the clash of metal break out to the south.>\n\nBy the light... they are here!", objectives = "Speak with Anchorite Traska at the Quel'Danil Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27726] = { id = 27726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Mount Hyjal!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", progress = "Help us!", completion = "We knew the Alliance would send help and not a moment too soon!", objectives = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27727] = { id = 27727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Deepholm!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.\n\nThe Earthen Ring requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world and destroy all life on Azeroth!\n\nThe Eastern Earthshrine can be found directly northwest of Stormwind Keep.\n\nFor the glory and honor of the Alliance! Fight on, <brother/sister>!", completion = "Our world is in danger, {name}! We need the help of great heroes, like you, to save it!", objectives = "Speak with Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[27729] = { id = 27729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More, With Eeling", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", objectives = "Kill 8 of any Eel in the Kelp Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
